    ('f38d4b41-f101-560d-88b6-cf200be8583d'::uuid, 'fiches'),
    ('c0fd943c-2302-5f3f-ae94-c4ffef827b57'::uuid, 'fiches'),
    ('9fe9cd1b-9a25-5a09-8d19-926d111d5b19'::uuid, 'fiches'),
    ('518de91f-e5fb-5db6-8a07-14a13815417e'::uuid, 'fiches'),
    ('32bf00b0-1af4-5b21-99f3-59a6eadf6c13'::uuid, 'fiches'),
    ('b9dff0bb-14b0-5257-9097-342941555cd0'::uuid, 'fiches'),
    ('a9c0c8dd-ca06-56f0-8447-c6b530d1ef2e'::uuid, 'fiches'),
    ('8579f291-a80b-519f-9353-2b6ac8c2c70a'::uuid, 'fiches'),
    ('4e9588ec-821a-5c55-8f8c-3e66a2fb68ac'::uuid, 'fiches'),
