    ('917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Quiz — Rousseau, 1758 — contre le théâtre, et contre les Lumières', 'Français', '1re', 'Lettre à d’Alembert sur les spectacles, Jean-Jacques Rousseau', '9abbc4ac-4987-522f-957a-83a20bd19fa1'::uuid),
    ('e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Quiz — Graffigny, 1747 — une étrangère juge la France', 'Français', '1re', 'Lettres d’une Péruvienne, Françoise de Graffigny', '1d8b7c82-4dc0-5213-8982-ec05643357df'::uuid),
    ('f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'Quiz — Daudet, 1869 — la Provence racontée depuis Paris', 'Français', '1re', 'Lettres de mon moulin, Alphonse Daudet', '85916390-c594-5a8f-b626-cf5cceb56cbc'::uuid),
    ('f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Quiz — Montesquieu, 1721 — le regard éloigné', 'Français', '1re', 'Lettres persanes, Montesquieu', 'ff5a9000-0954-5a93-a9f1-0456ae625a4d'::uuid),
    ('2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'Quiz — Sévigné, 1671-1696 — mille lettres à une fille', 'Français', '1re', 'Lettres, Madame de Sévigné', 'd83e1dc6-508c-5ede-b8bd-f85a172aae97'::uuid),
    ('cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Quiz — Musset, 1834 — le drame romantique impossible à jouer', 'Français', '1re', 'Lorenzaccio, Alfred de Musset', 'a53a6421-7369-57b4-98fc-2520a5d9e972'::uuid),
    ('11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'Quiz — Stendhal, 1894 — le roman inachevé de la monarchie de Juillet', 'Français', '1re', 'Lucien Leuwen, Stendhal', 'bffd012e-dbed-57c8-9ef2-e3e45cfaec02'::uuid),
    ('4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Quiz — Flaubert, 1857 — « Mœurs de province »', 'Français', '1re', 'Madame Bovary, Gustave Flaubert', '38b2511b-66c3-599a-9f0f-3bda5b8a1cad'::uuid),
    ('5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'Quiz — Gautier, 1835 — « l’art pour l’art », et un roman scandaleux', 'Français', '1re', 'Mademoiselle de Maupin, Théophile Gautier', 'd72acf05-34c9-5966-8ea2-8f66a593bea4'::uuid),
    ('5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'Quiz — Cohen, 1938 — la truculence des Valeureux', 'Français', '1re', 'Mangeclous, Albert Cohen', 'c21d8c53-d2a1-5dba-a5da-904fe347eb3a'::uuid),
    ('3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Quiz — Breton, 1924 — l’acte de naissance d’un mouvement', 'Français', '1re', 'Manifeste du Surréalisme, André Breton', '121abc32-d4d1-5754-92ed-03b2bd03bf8b'::uuid),
    ('b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Quiz — Pagnol, 1963 — la vengeance de la fille', 'Français', '1re', 'Manon des sources, Marcel Pagnol', 'd9eb6559-6a84-57d6-8023-d4d569342b77'::uuid),
    ('cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Quiz — Prévost, 1731 — la passion racontée par le coupable', 'Français', '1re', 'Manon Lescaut, abbé Prévost', 'e8345dbf-dc20-521e-856d-89b6c6b1cf8d'::uuid),
    ('80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'Quiz — Lamartine, 1820 — le premier recueil romantique', 'Français', '1re', 'Méditations poétiques, Alphonse de Lamartine', 'e4d1d8f5-65df-56fb-8cba-29e632b09176'::uuid),
    ('03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Quiz — Yourcenar, 1951 — la conscience d’un empereur', 'Français', '1re', 'Mémoires d’Hadrien, Marguerite Yourcenar', 'a2d334e3-e4b0-57d5-817d-85fe580ae052'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('4b407523-bce5-51f7-a88a-6bca2095a4e7'::uuid, '15396852-9543-5c47-98f3-0ff62a27d163'::uuid, 'À quel mouvement ce livre se rattache-t-il ?', 'mcq', '["Le symbolisme","Le naturalisme","Le surréalisme","Le classicisme"]'::jsonb, 0, 'Gide fréquentait alors les mardis de Mallarmé.', 1),
    ('a847a79d-5a17-5e79-bb15-fbd06aa27a69'::uuid, '15396852-9543-5c47-98f3-0ff62a27d163'::uuid, 'Quelles sont les trois étapes du voyage ?', 'mcq', '["L’Océan pathétique, la mer des Sargasses, la mer glaciale","La Méditerranée, l’Atlantique, le Pacifique","L’Afrique, l’Asie, l’Amérique","Le fleuve, la mer, le désert"]'::jsonb, 0, 'Chaque mer correspond à une épreuve spirituelle.', 2),
    ('50eabcc0-0bca-55ef-88b3-904f94789bf9'::uuid, '15396852-9543-5c47-98f3-0ff62a27d163'::uuid, 'Que découvre-t-on à la fin du récit ?', 'mcq', '["Que le voyage a été rêvé et n’a pas eu lieu","Que le pôle est habité","Qu’Urien est mort en mer","Que les compagnons se sont trahis"]'::jsonb, 0, 'Le renversement final annule tout ce qui précède.', 3),
    ('38764a1c-1dbd-5bfc-9f67-6f0a94363131'::uuid, '15396852-9543-5c47-98f3-0ff62a27d163'::uuid, 'Quel âge a Gide au moment de la publication ?', 'mcq', '["Vingt-quatre ans","Trente-cinq ans","Dix-huit ans","Quarante ans"]'::jsonb, 0, 'C’est son premier livre publié sous son nom, en 1893.', 4),
    ('f29f0771-4631-581e-92cf-59e341b9f566'::uuid, '15396852-9543-5c47-98f3-0ff62a27d163'::uuid, 'Quels thèmes gidiens ce livre annonce-t-il ?', 'mcq', '["La tentation du renoncement et l’ambiguïté du désir","La critique du colonialisme","Le roman policier","La satire sociale"]'::jsonb, 0, 'Ils traverseront toute son œuvre.', 5),
    ('99d43cff-ae70-5916-8125-707a9e06d7a2'::uuid, '15396852-9543-5c47-98f3-0ff62a27d163'::uuid, 'Gide considérait ce livre comme son chef-d’œuvre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en a plus tard ironisé, comme d’un livre de jeunesse.', 6),
    ('12093a65-8b27-5a74-9e36-86fd4822282a'::uuid, '8ce895fc-9f3b-52c6-9904-01b41f75eb52'::uuid, 'Combien de recueils Corbière a-t-il publiés ?', 'mcq', '["Un seul, Les Amours jaunes","Trois","Une dizaine","Aucun de son vivant"]'::jsonb, 0, 'Publié à compte d’auteur en 1873, il passa inaperçu.', 1),
    ('8b4d4e44-3469-53fc-9e42-c744771ab944'::uuid, '8ce895fc-9f3b-52c6-9904-01b41f75eb52'::uuid, 'Qui a sauvé Corbière de l’oubli ?', 'mcq', '["Verlaine, dans Les Poètes maudits","Baudelaire","Mallarmé","Hugo"]'::jsonb, 0, 'Il l’y place en tête, dix ans après la publication.', 2),
    ('c6ddecce-1254-5adc-819a-1c5744883a5c'::uuid, '8ce895fc-9f3b-52c6-9904-01b41f75eb52'::uuid, 'Que signifie le « jaune » du titre ?', 'mcq', '["Le rire jaune : l’ironie tournée contre soi","La couleur des blés","La maladie du poète","Le jaune des vieux papiers"]'::jsonb, 0, 'Corbière sabote lui-même ses propres élans.', 3),
    ('e816dd00-f2aa-5d64-93f2-ccd1b5f42970'::uuid, '8ce895fc-9f3b-52c6-9904-01b41f75eb52'::uuid, 'Quels univers nourrissent le recueil ?', 'mcq', '["La Bretagne, la mer et les marins","Paris et les salons","L’Italie","Les colonies"]'::jsonb, 0, '« La Rapsode foraine » et les poèmes marins en témoignent.', 4),
    ('39c25cc5-d06c-5571-886d-52b8ef4a2b4f'::uuid, '8ce895fc-9f3b-52c6-9904-01b41f75eb52'::uuid, 'Comment le poète se peint-il ?', 'mcq', '["Laid, malade et raté","Héroïque","Prophète","Dandy triomphant"]'::jsonb, 0, '« Le Crapaud » et « Épitaphe » sont exemplaires.', 5),
    ('3acd2e28-7532-5092-9394-24a143dddec4'::uuid, '8ce895fc-9f3b-52c6-9904-01b41f75eb52'::uuid, 'Corbière a connu la gloire de son vivant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est mort à trente ans, totalement ignoré.', 6),
    ('e8581066-a5f6-5853-96db-dbd5559a3f7a'::uuid, '3cda93d0-89cb-5cb3-a297-46f6a06f9b25'::uuid, 'Quel groupe Ronsard dirige-t-il ?', 'mcq', '["La Pléiade","Le Parnasse","Les Grands Rhétoriqueurs","Le Cénacle"]'::jsonb, 0, 'Avec Du Bellay, Baïf, Jodelle et leurs compagnons.', 1),
    ('c9fab76f-62b6-5d93-a52b-22880078891b'::uuid, '3cda93d0-89cb-5cb3-a297-46f6a06f9b25'::uuid, 'Quelle forme Ronsard installe-t-il en français ?', 'mcq', '["Le sonnet","Le rondeau","La ballade","Le vers libre"]'::jsonb, 0, 'Sur le modèle italien de Pétrarque.', 2),
    ('e258763e-58b9-5eea-b3e4-666dc3cfefb6'::uuid, '3cda93d0-89cb-5cb3-a297-46f6a06f9b25'::uuid, 'À qui s’adressent les sonnets de 1578 ?', 'mcq', '["À Hélène de Surgères","À Cassandre Salviati","À Marie Dupin","À Catherine de Médicis"]'::jsonb, 0, 'C’est le cycle du « Quand vous serez bien vieille… ».', 3),
    ('6fff6abf-3a90-5553-96fd-efa7ddae0d1d'::uuid, '3cda93d0-89cb-5cb3-a297-46f6a06f9b25'::uuid, 'Quel thème traverse tous les cycles ?', 'mcq', '["Le carpe diem et la fuite du temps","La guerre","La foi religieuse","Le voyage"]'::jsonb, 0, 'La beauté se fane, la poésie seule dure.', 4),
    ('a100604b-01a3-507b-bfb4-df1ed209c9bf'::uuid, '3cda93d0-89cb-5cb3-a297-46f6a06f9b25'::uuid, 'Quelle est la particularité des Amours de Marie ?', 'mcq', '["Un « beau style bas », plus simple et plus sensuel","Un style plus savant","L’usage du latin","L’absence de sonnets"]'::jsonb, 0, 'Ronsard s’y éloigne du pétrarquisme des débuts.', 5),
    ('6bc45918-cab7-519d-8856-4d89a9257f31'::uuid, '3cda93d0-89cb-5cb3-a297-46f6a06f9b25'::uuid, 'Ronsard écrit ses trois cycles à la même période de sa vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils s’étalent sur plus de vingt-cinq ans, de 1552 à 1578.', 6),
    ('e1713ea6-d0cd-54e5-8c78-fbfc3fb39025'::uuid, '75f62dbd-f651-5a5c-a613-51690ac56526'::uuid, 'Pour qui Fénelon a-t-il écrit ce livre ?', 'mcq', '["Le duc de Bourgogne, petit-fils de Louis XIV","Louis XIV lui-même","Le Régent","Les élèves d’un collège"]'::jsonb, 0, 'Fénelon était son précepteur.', 1),
    ('6ab8421c-f72d-53da-a7d0-a0ff7ef6e550'::uuid, '75f62dbd-f651-5a5c-a613-51690ac56526'::uuid, 'Qui accompagne Télémaque ?', 'mcq', '["Mentor, qui est en réalité Minerve","Ulysse","Calypso","Nestor"]'::jsonb, 0, 'Le nom « mentor » est devenu un nom commun grâce à ce livre.', 2),
    ('8db7ab1c-f167-58d2-84dd-675a5fe185b7'::uuid, '75f62dbd-f651-5a5c-a613-51690ac56526'::uuid, 'Que sont la Bétique et Salente ?', 'mcq', '["Deux États modèles décrits comme exemples politiques","Deux batailles","Deux personnages féminins","Deux navires"]'::jsonb, 0, 'Mentor y réforme le gouvernement sous les yeux du lecteur.', 3),
    ('eaea0ca5-bd8b-5027-bac8-a335a2b8152e'::uuid, '75f62dbd-f651-5a5c-a613-51690ac56526'::uuid, 'Comment le livre a-t-il été reçu à la cour ?', 'mcq', '["Comme une critique du règne de Louis XIV, ce qui valut la disgrâce à Fénelon","Comme un hommage au roi","Avec indifférence","Comme un simple livre pour enfants"]'::jsonb, 0, 'Guerre, luxe et orgueil y sont visés.', 4),
    ('893e611d-d253-5fbc-b9fe-880571f497ca'::uuid, '75f62dbd-f651-5a5c-a613-51690ac56526'::uuid, 'Quel genre le livre contribue-t-il à fonder ?', 'mcq', '["Le roman d’éducation","Le roman policier","Le roman épistolaire","Le conte fantastique"]'::jsonb, 0, 'Il fut l’un des livres les plus lus du XVIIIe siècle.', 5),
    ('b0a74ff9-570c-58e2-b0e5-06a0fcafde6e'::uuid, '75f62dbd-f651-5a5c-a613-51690ac56526'::uuid, 'Fénelon a lui-même autorisé la publication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le livre a paru sans son accord, en 1699.', 6),
    ('918b2dae-7831-57a9-8290-cce605a493a6'::uuid, 'f10de73e-ae16-5eac-8c70-b96f85bcf1cd'::uuid, 'Que font Claire et Solange en l’absence de Madame ?', 'mcq', '["Elles jouent une cérémonie où l’une prend le rôle de Madame","Elles fouillent la maison","Elles écrivent des lettres","Elles reçoivent des amis"]'::jsonb, 0, 'Le jeu va toujours jusqu’au bord du meurtre.', 1),
    ('d16c6ea2-1eab-5501-8c11-aca8ceaf58eb'::uuid, 'f10de73e-ae16-5eac-8c70-b96f85bcf1cd'::uuid, 'Qu’ont fait les deux sœurs avant le début de la pièce ?', 'mcq', '["Elles ont dénoncé Monsieur par des lettres anonymes","Elles ont volé des bijoux","Elles ont incendié la maison","Elles ont fui"]'::jsonb, 0, 'Sa libération précipite la catastrophe.', 2),
    ('56f8653c-ae52-5aa1-9b11-feb73d760a7f'::uuid, 'f10de73e-ae16-5eac-8c70-b96f85bcf1cd'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Claire, jouant Madame, boit le tilleul empoisonné et meurt","Madame boit le poison","Les sœurs sont arrêtées","Rien ne se passe"]'::jsonb, 0, 'Le crime devient enfin réel, à l’intérieur du jeu.', 3),
    ('294c3042-9369-5995-88d2-bec6ef512e6a'::uuid, 'f10de73e-ae16-5eac-8c70-b96f85bcf1cd'::uuid, 'De quel fait divers la pièce s’inspire-t-elle ?', 'mcq', '["L’affaire des sœurs Papin, en 1933","L’affaire Dreyfus","L’affaire Landru","Aucun fait réel"]'::jsonb, 0, 'Genet en fait une cérémonie, non une reconstitution.', 4),
    ('a163ae0f-fd9b-5e69-add6-a7d935ee0c91'::uuid, 'f10de73e-ae16-5eac-8c70-b96f85bcf1cd'::uuid, 'Quel procédé théâtral structure la pièce ?', 'mcq', '["Le théâtre dans le théâtre : des rôles joués par des personnages","Le monologue continu","Le chœur antique","La narration en voix off"]'::jsonb, 0, 'Genet exige masques et rôles, contre le réalisme.', 5),
    ('9e11a3bf-8321-5f2b-b0cb-e066320075cc'::uuid, 'f10de73e-ae16-5eac-8c70-b96f85bcf1cd'::uuid, 'Genet écrit une langue volontairement pauvre pour ses personnages humbles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il écrit au contraire une langue somptueuse pour dire les humiliés.', 6),
    ('b20ff0de-f7c5-544f-837b-af1eef596aa5'::uuid, 'b69b76d6-de29-57dd-8b47-c2190e53593d'::uuid, 'Quand la pièce a-t-elle été créée ?', 'mcq', '["En 1843","En 1830","En 1827","En 1862"]'::jsonb, 0, 'La même année que la mort de Léopoldine, quelques mois plus tard.', 1),
    ('d0290fbb-5276-5bfd-9949-a701db4c8a02'::uuid, 'b69b76d6-de29-57dd-8b47-c2190e53593d'::uuid, 'Qui sont les burgraves ?', 'mcq', '["Des seigneurs brigands des bords du Rhin","Des moines allemands","Des marchands hanséatiques","Des chevaliers croisés"]'::jsonb, 0, 'Trois générations vivent sous le même toit.', 2),
    ('aa54eb9f-e043-5bb8-af29-f7c0c622531f'::uuid, 'b69b76d6-de29-57dd-8b47-c2190e53593d'::uuid, 'Qui se révèle être le mendiant mystérieux ?', 'mcq', '["L’empereur Frédéric Barberousse","Le frère de Job","Un envoyé du pape","Un burgrave rival"]'::jsonb, 0, 'Il revient pour juger les siens.', 3),
    ('c81288ed-4d00-54d1-8c55-10d1d4315b11'::uuid, 'b69b76d6-de29-57dd-8b47-c2190e53593d'::uuid, 'Quel événement théâtral cet échec marque-t-il ?', 'mcq', '["La fin du drame romantique à la scène","Le début du théâtre symboliste","La naissance du vaudeville","La fermeture des théâtres"]'::jsonb, 0, 'Le triomphe simultané de Lucrèce, néoclassique, en est le symbole.', 4),
    ('0b5867c6-e513-59e4-a1af-5166ea70ce56'::uuid, 'b69b76d6-de29-57dd-8b47-c2190e53593d'::uuid, 'Que fait Hugo après cet échec ?', 'mcq', '["Il cesse d’écrire pour la scène","Il écrit trois nouvelles pièces","Il fonde un théâtre","Il traduit Shakespeare"]'::jsonb, 0, 'Le Théâtre en liberté ne sera pas destiné à la représentation.', 5),
    ('c20a4006-0a37-5f74-b1ec-dcf87260a517'::uuid, 'b69b76d6-de29-57dd-8b47-c2190e53593d'::uuid, 'La pièce fut un triomphe public.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce fut un échec retentissant, resté célèbre comme tel.', 6),
    ('7f3b3f8e-7d72-58d1-8655-ef930c42f31c'::uuid, '46da64ea-8983-5d91-961e-234caa3e5482'::uuid, 'Comment ce premier livre a-t-il été publié ?', 'mcq', '["Anonymement, en 1891","Sous le nom de Gide","Sous un pseudonyme féminin","À titre posthume"]'::jsonb, 0, 'Gide avait vingt et un ans.', 1),
    ('ff250221-1fae-533a-86b2-ba95bc61cc0d'::uuid, '46da64ea-8983-5d91-961e-234caa3e5482'::uuid, 'Quelle forme prend le livre ?', 'mcq', '["Les cahiers posthumes d’un jeune homme mort fou","Un roman à la troisième personne","Un recueil de poèmes","Une pièce de théâtre"]'::jsonb, 0, 'Deux parties : le Cahier blanc et le Cahier noir.', 2),
    ('9b611683-fc9d-5861-8d3b-94d2e593f2c9'::uuid, '46da64ea-8983-5d91-961e-234caa3e5482'::uuid, 'Pourquoi Walter renonce-t-il à épouser Emmanuèle ?', 'mcq', '["Sa mère mourante le lui a fait promettre","Elle en aime un autre","Il est trop pauvre","Elle entre au couvent"]'::jsonb, 0, 'Il choisit alors l’amour pur et refuse le corps.', 3),
    ('95d8d7ad-ed2f-587b-9e5a-346fea3dbeb3'::uuid, '46da64ea-8983-5d91-961e-234caa3e5482'::uuid, 'Qui se cache derrière le personnage d’Emmanuèle ?', 'mcq', '["Madeleine Rondeaux, cousine que Gide épousera","Une amie d’enfance imaginaire","Sa mère","Une actrice parisienne"]'::jsonb, 0, 'Leur mariage, en 1895, restera blanc.', 4),
    ('60300932-86f2-584c-b0cf-66f60aef03cb'::uuid, '46da64ea-8983-5d91-961e-234caa3e5482'::uuid, 'Quelle tension fondatrice le livre installe-t-il ?', 'mcq', '["Le conflit entre le corps et l’esprit","L’opposition ville-campagne","Le conflit des générations","La lutte des classes"]'::jsonb, 0, 'Elle traversera toute l’œuvre de Gide.', 5),
    ('2fbd4347-b337-5d0b-90d2-bc3368855f5e'::uuid, '46da64ea-8983-5d91-961e-234caa3e5482'::uuid, 'Gide a toujours défendu ce livre comme une réussite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le jugera plus tard avec sévérité, comme un livre trop marqué par son époque.', 6),
    ('1c766812-66f8-5509-bd20-9d35b4799f3e'::uuid, 'a43604ec-6f82-59fc-916c-85363b9fc3d8'::uuid, 'Combien de poèmes compte l’ensemble ?', 'mcq', '["Vingt-deux","Douze","Cinquante","Trente"]'::jsonb, 0, 'Recopiés en deux liasses chez Paul Demeny.', 1),
    ('6460338d-4044-5e84-8f00-735891a6eee0'::uuid, 'a43604ec-6f82-59fc-916c-85363b9fc3d8'::uuid, 'Quel âge a Rimbaud à l’automne 1870 ?', 'mcq', '["Quinze et seize ans","Dix-huit ans","Vingt ans","Quatorze ans"]'::jsonb, 0, 'C’est un argument central du parcours « émancipations créatrices ».', 2),
    ('0807fa48-f364-522d-8084-0b58353c0bde'::uuid, 'a43604ec-6f82-59fc-916c-85363b9fc3d8'::uuid, 'Quel événement historique nourrit les poèmes satiriques ?', 'mcq', '["La guerre franco-prussienne et la chute du Second Empire","La Commune de Paris","La Révolution de 1848","La guerre de Crimée"]'::jsonb, 0, '« Rages de Césars » et « Le Mal » en sont issus.', 3),
    ('11e5c6b7-40cc-5eb8-88e9-9844b69b92f3'::uuid, 'a43604ec-6f82-59fc-916c-85363b9fc3d8'::uuid, 'Quelle est la chute du « Dormeur du val » ?', 'mcq', '["Le soldat est mort : « deux trous rouges au côté droit »","Le soldat se réveille","La nature se fane","Le poète s’endort à son tour"]'::jsonb, 0, 'Treize vers de nature riante préparent la révélation.', 4),
    ('319a643b-3cb7-5070-8ff5-7835693597bc'::uuid, 'a43604ec-6f82-59fc-916c-85363b9fc3d8'::uuid, 'Le titre du recueil a-t-il été choisi par Rimbaud ?', 'mcq', '["Non, il est posthume","Oui, dès 1870","Oui, dans une lettre à Demeny","Il a été choisi par Verlaine avec son accord"]'::jsonb, 0, 'Ce n’est pas un recueil composé par son auteur.', 5),
    ('4e9418e2-f5db-5fec-aa63-2b37cf0af05b'::uuid, 'a43604ec-6f82-59fc-916c-85363b9fc3d8'::uuid, 'Rimbaud rejette la forme du sonnet dans ces poèmes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’emploie et la maltraite de l’intérieur, par les enjambements et le vocabulaire.', 6),
    ('93b6aecf-e290-5ec4-a938-46a6ffe93973'::uuid, '077d5a9f-70f1-51ba-a070-4a958d2f07ce'::uuid, 'Comment l’ouvrage se présente-t-il d’abord ?', 'mcq', '["Comme une traduction de Théophraste","Comme un roman","Comme un traité de morale","Comme un recueil de lettres"]'::jsonb, 0, 'Les remarques personnelles finiront par occuper tout le livre.', 1),
    ('f93283c3-c5bc-50bc-912f-84766aa6b285'::uuid, '077d5a9f-70f1-51ba-a070-4a958d2f07ce'::uuid, 'Que montrent les portraits de Giton et Phédon ?', 'mcq', '["Le corps et les manières trahissent la condition sociale","La richesse rend généreux","La pauvreté est méritée","Les nobles sont ridicules"]'::jsonb, 0, 'Giton occupe l’espace, Phédon s’efface.', 2),
    ('fcf24f8b-072c-5e3d-af4b-c4a9c1ad2459'::uuid, '077d5a9f-70f1-51ba-a070-4a958d2f07ce'::uuid, 'Quel livre est considéré comme le sommet de l’œuvre ?', 'mcq', '["« De la cour »","« Des femmes »","« De l’homme »","« Des ouvrages de l’esprit »"]'::jsonb, 0, '« L’on s’élève à la cour, mais on n’y monte pas. »', 3),
    ('5518ab37-5f8b-532e-a0b0-2dd93ead1294'::uuid, '077d5a9f-70f1-51ba-a070-4a958d2f07ce'::uuid, 'Pourquoi les personnages portent-ils des noms grecs ?', 'mcq', '["Pour protéger l’auteur tout en laissant reconnaître les modèles","Par goût de l’Antiquité","Parce que le livre est traduit du grec","Pour imiter Homère"]'::jsonb, 0, 'Des « clés » circulaient à la cour.', 4),
    ('b3f35876-a8ac-5514-b88b-c72b128c2c96'::uuid, '077d5a9f-70f1-51ba-a070-4a958d2f07ce'::uuid, 'Quelle phrase ouvre le livre ?', 'mcq', '["« Tout est dit, et l’on vient trop tard »","« Je ne peins pas l’être »","« Le cœur a ses raisons »","« L’homme est un roseau pensant »"]'::jsonb, 0, 'Elle justifie le choix du fragment.', 5),
    ('413df594-2924-5edc-9b2d-2930b615198e'::uuid, '077d5a9f-70f1-51ba-a070-4a958d2f07ce'::uuid, 'La Bruyère procède par démonstrations suivies.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il montre plutôt qu’il ne démontre : un geste suffit à faire un caractère.', 6),
    ('12a9c1bd-b352-5462-9b1b-e0251f44d8bf'::uuid, '7997c089-8fbd-5a48-a7a7-ad476cda7139'::uuid, 'Comment Gide appelle-t-il ce livre ?', 'mcq', '["Une sotie, farce satirique","Un récit","Un roman","Un essai"]'::jsonb, 0, 'Il réservait le mot « roman » aux Faux-Monnayeurs.', 1),
    ('b4668c09-4818-5e1a-8e96-9a4370340f9e'::uuid, '7997c089-8fbd-5a48-a7a7-ad476cda7139'::uuid, 'Quelle escroquerie est au centre du livre ?', 'mcq', '["Faire croire que le pape est séquestré pour lever des fonds","Un faux héritage","La vente d’une fausse relique","Un trafic de titres"]'::jsonb, 0, 'Protos mène la bande.', 2),
    ('07ad54fa-289f-529a-a7ad-64d540a5181d'::uuid, '7997c089-8fbd-5a48-a7a7-ad476cda7139'::uuid, 'Qu’est-ce que l’acte gratuit ?', 'mcq', '["Un acte sans motif, censé prouver la liberté","Un don charitable","Un crime prémédité","Un pari perdu"]'::jsonb, 0, 'Lafcadio pousse Fleurissoire hors du train sans raison.', 3),
    ('a651ffba-843d-567b-82bc-36d4b4698c91'::uuid, '7997c089-8fbd-5a48-a7a7-ad476cda7139'::uuid, 'Qui part à Rome délivrer le pape ?', 'mcq', '["Amédée Fleurissoire","Julius de Baraglioul","Anthime Armand-Dubois","Protos"]'::jsonb, 0, 'Sa naïveté est le moteur comique du livre.', 4),
    ('7c6e1a97-b7ba-55a3-a91b-904c809de756'::uuid, '7997c089-8fbd-5a48-a7a7-ad476cda7139'::uuid, 'Quel mouvement littéraire a admiré la notion d’acte gratuit ?', 'mcq', '["Le surréalisme","Le naturalisme","Le Parnasse","Le classicisme"]'::jsonb, 0, 'Gide lui-même l’a ensuite relativisée.', 5),
    ('1a84270c-aa2b-5e82-8470-439fa1380572'::uuid, '7997c089-8fbd-5a48-a7a7-ad476cda7139'::uuid, 'Lafcadio échappe à toute conséquence après son geste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est rattrapé par la logique des faits et par le remords.', 6),
    ('131f1a0d-6261-5452-a1c8-c52abb2d35fa'::uuid, '6889dedb-c879-57f2-a294-e81a9992ac96'::uuid, 'Qui sont les invités du couple de vieillards ?', 'mcq', '["Des invités invisibles","Des voisins du village","Des journalistes","Leur famille"]'::jsonb, 0, 'Le couple leur parle et leur apporte des chaises.', 1),
    ('6544ba6b-2540-5237-8afa-fc8248c2ebb9'::uuid, '6889dedb-c879-57f2-a294-e81a9992ac96'::uuid, 'Qu’est-ce qui envahit progressivement la scène ?', 'mcq', '["Les chaises","L’eau","Les meubles du salon","Des livres"]'::jsonb, 0, 'La prolifération des objets est un thème constant chez Ionesco.', 2),
    ('07d2409c-e997-5568-a8be-0abd9ad054b0'::uuid, '6889dedb-c879-57f2-a294-e81a9992ac96'::uuid, 'Que doit faire l’Orateur ?', 'mcq', '["Transmettre le message capital du Vieux","Diriger la cérémonie","Juger le couple","Annoncer l’Empereur"]'::jsonb, 0, 'Les vieux se jettent par la fenêtre, rassurés.', 3),
    ('af29586c-abbb-5fbe-bdf2-02212afde0e9'::uuid, '6889dedb-c879-57f2-a294-e81a9992ac96'::uuid, 'Quelle est la révélation finale ?', 'mcq', '["L’Orateur est sourd-muet et ne peut rien transmettre","Le message est écrit dans un livre","Les invités deviennent visibles","L’Empereur parle à sa place"]'::jsonb, 0, 'Il trace au tableau des lettres sans signification.', 4),
    ('b32c3808-dff1-5941-a490-4c29a2fa43b3'::uuid, '6889dedb-c879-57f2-a294-e81a9992ac96'::uuid, 'Comment Ionesco sous-titre-t-il la pièce ?', 'mcq', '["« Farce tragique »","« Comédie noire »","« Drame lyrique »","« Anti-pièce »"]'::jsonb, 0, '« Anti-pièce » est le sous-titre de La Cantatrice chauve.', 5),
    ('17052aa6-6a5b-5cbe-a124-bd0900426127'::uuid, '6889dedb-c879-57f2-a294-e81a9992ac96'::uuid, 'La pièce affirme la puissance du langage à transmettre un sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle porte à son sommet le thème du langage impuissant.', 6),
    ('2f58aa10-a1de-51c3-8eef-d169686efe39'::uuid, '64e6ceab-4369-591b-95dc-e7129aa777db'::uuid, 'Contre qui le recueil est-il dirigé ?', 'mcq', '["Louis-Napoléon Bonaparte, après le coup d’État de 1851","Louis-Philippe","Charles X","Thiers"]'::jsonb, 0, 'Hugo l’appelle « Napoléon le Petit ».', 1),
    ('5aa1ad52-811c-5ebf-827a-29d1265f8956'::uuid, '64e6ceab-4369-591b-95dc-e7129aa777db'::uuid, 'Où le recueil a-t-il été publié ?', 'mcq', '["À Bruxelles, en 1853, et interdit en France","À Paris","À Londres, en 1860","À Genève, en 1870"]'::jsonb, 0, 'Il circulait clandestinement en France.', 2),
    ('73105a11-9d7b-5414-826b-df9285ef5f21'::uuid, '64e6ceab-4369-591b-95dc-e7129aa777db'::uuid, 'Quel poème raconte la mort d’un enfant lors du coup d’État ?', 'mcq', '["Souvenir de la nuit du 4","L’expiation","Lux","Chanson"]'::jsonb, 0, 'La grand-mère y déshabille l’enfant tué par les balles.', 3),
    ('8a533c5e-f35d-539a-9a0c-8a484b997952'::uuid, '64e6ceab-4369-591b-95dc-e7129aa777db'::uuid, 'Que raconte « L’expiation » ?', 'mcq', '["Waterloo, la Bérézina et Sainte-Hélène, pour écraser le neveu par l’oncle","La mort de Léopoldine","L’exil de Hugo","Le sacre de Napoléon III"]'::jsonb, 0, 'L’ombre du grand Napoléon accable le petit.', 4),
    ('40166121-71b1-5785-a83a-bc6cc99874bc'::uuid, '64e6ceab-4369-591b-95dc-e7129aa777db'::uuid, 'Comment les titres des sept livres sont-ils construits ?', 'mcq', '["Ils reprennent ironiquement les slogans du régime","Ils suivent l’ordre chronologique","Ils portent des noms de villes","Ils sont numérotés seulement"]'::jsonb, 0, '« L’ordre est rétabli », « La société est sauvée »…', 5),
    ('17ad1c87-bf82-522e-afbd-910c8f5352c9'::uuid, '64e6ceab-4369-591b-95dc-e7129aa777db'::uuid, 'Hugo a accepté l’amnistie de 1859.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Quand la liberté rentrera, je rentrerai » : il restera dix-neuf ans en exil.', 6),
    ('6484b3d9-aa8e-59cc-93d1-b0dcc9618378'::uuid, 'f5ff80c9-e10a-58fe-9afa-0bf94b0a54b8'::uuid, 'Quelle forme populaire le recueil reprend-il ?', 'mcq', '["La complainte de rue, avec couplets et refrains","Le sonnet","La ballade médiévale","L’ode antique"]'::jsonb, 0, 'Cinquante complaintes en composent le recueil.', 1),
    ('1b0a716d-ea9b-509a-9972-151a77ae7d24'::uuid, 'f5ff80c9-e10a-58fe-9afa-0bf94b0a54b8'::uuid, 'Quel type de mots Laforgue invente-t-il ?', 'mcq', '["Des mots-valises comme « éternullité » ou « violupté »","Des mots latins","Des noms propres imaginaires","Des onomatopées uniquement"]'::jsonb, 0, 'Il casse le vers et la langue de l’intérieur.', 2),
    ('88bce4cc-e339-5aa7-8d17-55fb833db408'::uuid, 'f5ff80c9-e10a-58fe-9afa-0bf94b0a54b8'::uuid, 'Quel rôle joue l’ironie chez Laforgue ?', 'mcq', '["Elle empêche l’épanchement de devenir ridicule","Elle sert la satire politique","Elle vise le lecteur","Elle imite Voltaire"]'::jsonb, 0, 'C’est une politesse envers le lecteur et envers soi.', 3),
    ('99f42c87-900e-569b-be11-b0fc65ef0a93'::uuid, 'f5ff80c9-e10a-58fe-9afa-0bf94b0a54b8'::uuid, 'De quelle innovation formelle Laforgue est-il un pionnier ?', 'mcq', '["Le vers libre","Le poème en prose","Le calligramme","Le sonnet renversé"]'::jsonb, 0, 'Ses Derniers vers, posthumes, en sont le meilleur exemple.', 4),
    ('8a585e18-e92b-5cca-b330-1005e027ea86'::uuid, 'f5ff80c9-e10a-58fe-9afa-0bf94b0a54b8'::uuid, 'Quel poète anglo-américain revendiquait son influence ?', 'mcq', '["T. S. Eliot","Walt Whitman","Lord Byron","Emily Dickinson"]'::jsonb, 0, 'Son influence dépasse largement sa notoriété.', 5),
    ('d588ef68-2312-5edd-9b01-fb0911030152'::uuid, 'f5ff80c9-e10a-58fe-9afa-0bf94b0a54b8'::uuid, 'Laforgue a connu une longue carrière poétique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est mort de tuberculose à vingt-sept ans, deux ans après ce recueil.', 6),
    ('fb892ee9-0a1c-5d83-b2c6-32d596cd89bc'::uuid, '614bd76c-c06d-54bb-b722-2f062148b466'::uuid, 'Quel projet Rousseau annonce-t-il dès la première page ?', 'mcq', '["Montrer un homme dans toute la vérité de la nature : lui-même","Écrire l’histoire de son siècle","Corriger ses ennemis","Composer un traité d’éducation"]'::jsonb, 0, 'L’entreprise se veut sans exemple.', 1),
    ('fdf18cf8-5400-5033-98bd-e1cba3ed4504'::uuid, '614bd76c-c06d-54bb-b722-2f062148b466'::uuid, 'Quand l’œuvre a-t-elle été publiée ?', 'mcq', '["Après sa mort, en 1782 et 1789","De son vivant, en 1770","En 1750","Au XIXe siècle seulement"]'::jsonb, 0, 'Six livres d’abord, six ensuite.', 2),
    ('78869b38-c1f6-5f2f-8960-f316bf6b33ec'::uuid, '614bd76c-c06d-54bb-b722-2f062148b466'::uuid, 'Quel épisode d’aveu est resté célèbre ?', 'mcq', '["Le ruban volé dont il accuse la servante Marion","Le vol d’un cheval","Un duel manqué","Une lettre falsifiée"]'::jsonb, 0, 'Il en a porté le remords toute sa vie, dit-il.', 3),
    ('4fec5f94-e8d0-527f-a53e-6ae989367c02'::uuid, '614bd76c-c06d-54bb-b722-2f062148b466'::uuid, 'Qui est « Maman » dans les Confessions ?', 'mcq', '["Madame de Warens","Sa mère, morte à sa naissance","Thérèse Levasseur","Madame d’Épinay"]'::jsonb, 0, 'Elle le recueille, l’instruit et devient sa maîtresse.', 4),
    ('f72d40e3-902d-55f2-8d7e-60e4733b371f'::uuid, '614bd76c-c06d-54bb-b722-2f062148b466'::uuid, 'Quel genre le livre fonde-t-il ?', 'mcq', '["L’autobiographie moderne","Le roman épistolaire","L’essai","Le journal intime"]'::jsonb, 0, 'Enfance, sensations, aveu des fautes, primauté du sentiment.', 5),
    ('b3858d88-489e-50cb-8b39-b093516a3c1c'::uuid, '614bd76c-c06d-54bb-b722-2f062148b466'::uuid, 'Rousseau tait ses fautes pour se présenter sous un jour flatteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il revendique l’aveu, y compris l’abandon de ses enfants.', 6),
    ('32864cae-461c-5015-beee-a4fae43a8a97'::uuid, '1c8bb3a8-e475-52ee-82f8-8b6fb7469792'::uuid, 'Comment le recueil est-il divisé ?', 'mcq', '["En Autrefois et Aujourd’hui, séparés par la mort de Léopoldine","En quatre saisons","Par ordre chronologique de composition","En trois parties égales"]'::jsonb, 0, 'Six livres au total.', 1),
    ('baaac425-1b27-5783-b199-0a32b204d948'::uuid, '1c8bb3a8-e475-52ee-82f8-8b6fb7469792'::uuid, 'Quelle formule de la préface résume le projet ?', 'mcq', '["« Quand je vous parle de moi, je vous parle de vous »","« Le poète est un phare »","« Je est un autre »","« Tout est dit »"]'::jsonb, 0, 'Le « je » lyrique y est offert comme un miroir.', 2),
    ('3af45be5-6e99-591c-97af-ce9d1cc78727'::uuid, '1c8bb3a8-e475-52ee-82f8-8b6fb7469792'::uuid, 'Quel poème évoque le travail des enfants à l’usine ?', 'mcq', '["Melancholia","Demain, dès l’aube…","À Villequier","Paroles sur la dune"]'::jsonb, 0, 'Hugo y est déjà le poète social des Misérables.', 3),
    ('48d0deac-773d-5995-bdea-22e1c8ddc08f'::uuid, '1c8bb3a8-e475-52ee-82f8-8b6fb7469792'::uuid, 'Quel poème est une visite à la tombe de sa fille ?', 'mcq', '["Demain, dès l’aube…","Réponse à un acte d’accusation","Ce que dit la bouche d’ombre","Vieille chanson du jeune temps"]'::jsonb, 0, 'Le poème ne le révèle qu’au dernier vers.', 4),
    ('95d8356e-660a-53d4-997c-6bb35f2df29c'::uuid, '1c8bb3a8-e475-52ee-82f8-8b6fb7469792'::uuid, 'Où Hugo se trouve-t-il lors de la publication ?', 'mcq', '["En exil à Guernesey","À Paris","En Belgique","À Jersey uniquement"]'::jsonb, 0, 'L’exil donne au livre sa position de retrait.', 5),
    ('c0d95a1d-3f68-500b-9231-a0d4b2e8e64d'::uuid, '1c8bb3a8-e475-52ee-82f8-8b6fb7469792'::uuid, 'Le recueil est une autobiographie factuelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le récit d’une vie intérieure : « les Mémoires d’une âme ».', 6),
    ('9a41e05b-4704-5316-91b1-280603899845'::uuid, '5b310bc5-376e-554c-ba54-4dde5a21779d'::uuid, 'Quand le recueil a-t-il été publié ?', 'mcq', '["En 1864, après la mort de Vigny","En 1826","En 1840","En 1856"]'::jsonb, 0, 'Les onze poèmes ont été écrits sur trente ans.', 1),
    ('3904c1e7-274d-51e1-a8d4-13ffc27c2ab5'::uuid, '5b310bc5-376e-554c-ba54-4dde5a21779d'::uuid, 'Quelle leçon donne « La Mort du loup » ?', 'mcq', '["Souffrir et mourir sans se plaindre : le stoïcisme","La revanche contre les hommes","La foi retrouvée","La fuite dans la nature"]'::jsonb, 0, '« Gémir, pleurer, prier est également lâche. »', 2),
    ('b01d041b-5a49-5e61-8d13-9262109d2100'::uuid, '5b310bc5-376e-554c-ba54-4dde5a21779d'::uuid, 'Quelle vision de la nature Vigny propose-t-il ?', 'mcq', '["Une nature indifférente aux hommes","Une nature consolatrice","Une nature divine et vivante","Une nature hostile et vengeresse"]'::jsonb, 0, 'Elle « roule avec dédain » : c’est l’opposé du romantisme de Lamartine.', 3),
    ('5234cd71-9d92-5c0b-bae1-5577344919c8'::uuid, '5b310bc5-376e-554c-ba54-4dde5a21779d'::uuid, 'Quel poème évoque le silence de Dieu ?', 'mcq', '["Le Mont des Oliviers","La Bouteille à la mer","L’Esprit pur","Les Destinées"]'::jsonb, 0, 'Le Christ y attend une réponse qui ne vient pas.', 4),
    ('ffc10c95-a194-567a-b7f1-447de6dc44d7'::uuid, '5b310bc5-376e-554c-ba54-4dde5a21779d'::uuid, 'Que symbolise « La Bouteille à la mer » ?', 'mcq', '["L’œuvre confiée à l’avenir","Le naufrage de l’amour","L’exil politique","La mort du savant"]'::jsonb, 0, 'Le savant y jette son travail à la mer pour qu’il survive.', 5),
    ('88731b4d-9a1e-58b6-b22a-cde775157363'::uuid, '5b310bc5-376e-554c-ba54-4dde5a21779d'::uuid, 'La poésie de Vigny est surtout lyrique et sentimentale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une poésie de la pensée : chaque poème démontre une idée par un symbole.', 6),
    ('5354c50c-d4fe-5f56-bcd6-95634a3f04a0'::uuid, '3211f7d1-de2b-5e86-b7ae-629ea3d635b5'::uuid, 'Qui organise le stratagème ?', 'mcq', '["Dubois, l’ancien valet de Dorante","Marton","Madame Argante","Le comte Dorimont"]'::jsonb, 0, 'Il est désormais au service d’Araminte.', 1),
    ('9b376458-602d-5e50-9b4f-b1a3d0d33316'::uuid, '3211f7d1-de2b-5e86-b7ae-629ea3d635b5'::uuid, 'Quelle « fausse confidence » lance l’intrigue ?', 'mcq', '["Dubois révèle à Araminte que Dorante l’aime depuis longtemps","Dorante se dit ruiné","Marton dénonce Dubois","Le comte annonce un mariage"]'::jsonb, 0, 'La confidence est vraie, mais son moment est calculé.', 2),
    ('9ecb1215-ed26-5ae7-b4ed-50345811a15a'::uuid, '3211f7d1-de2b-5e86-b7ae-629ea3d635b5'::uuid, 'Quel objet compromet Dorante ?', 'mcq', '["Un portrait d’Araminte","Une bague","Un contrat","Un billet de banque"]'::jsonb, 0, 'Il matérialise l’amour annoncé par Dubois.', 3),
    ('70b5286b-4929-5cfa-ab8f-177f2f3138a4'::uuid, '3211f7d1-de2b-5e86-b7ae-629ea3d635b5'::uuid, 'Comment Araminte éprouve-t-elle Dorante ?', 'mcq', '["Elle lui dicte une lettre annonçant son propre mariage","Elle le congédie","Elle lui offre de l’argent","Elle le fait suivre"]'::jsonb, 0, 'La scène est l’une des plus cruelles du théâtre de Marivaux.', 4),
    ('dbd4894d-2e35-567f-a24a-b92ec5bfdca0'::uuid, '3211f7d1-de2b-5e86-b7ae-629ea3d635b5'::uuid, 'Qu’est-ce qui rend le dénouement audacieux ?', 'mcq', '["Araminte épouse un homme sans fortune","Dorante refuse le mariage","Dubois est renvoyé","Marton épouse le comte"]'::jsonb, 0, 'Un scandale, du point de vue social de l’époque.', 5),
    ('b2370816-4ba4-5bec-ad75-2b262b743e5b'::uuid, '3211f7d1-de2b-5e86-b7ae-629ea3d635b5'::uuid, 'Le stratagème crée le sentiment amoureux de toutes pièces.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La pièce laisse les deux lectures ouvertes : il peut aussi n’avoir fait que lever les obstacles.', 6),
    ('f9e0219a-c144-511f-b3fb-fcbac36cb22f'::uuid, 'a57a24b0-3127-5477-8eae-d8347282c86c'::uuid, 'Quel procédé structure le roman ?', 'mcq', '["La mise en abyme : un romancier y écrit le même roman","Le récit à la première personne","Le monologue intérieur continu","La narration par lettres"]'::jsonb, 0, 'Édouard tient aussi un journal, inclus dans le livre.', 1),
    ('ad7ea711-5f2e-5bfe-9368-ea7984f26766'::uuid, 'a57a24b0-3127-5477-8eae-d8347282c86c'::uuid, 'Pourquoi Bernard quitte-t-il sa famille ?', 'mcq', '["Il découvre qu’il est un enfant illégitime","Il est renvoyé du lycée","Il fuit la police","Il part travailler"]'::jsonb, 0, 'Il devient ensuite le secrétaire d’Édouard.', 2),
    ('f4fd1294-2142-5deb-a2d0-b266f5837799'::uuid, 'a57a24b0-3127-5477-8eae-d8347282c86c'::uuid, 'Que désigne la « fausse monnaie » du titre ?', 'mcq', '["Autant les pièces fausses que les sentiments et les vertus feints","Un trafic bancaire","Une métaphore de la littérature seule","Une affaire judiciaire réelle"]'::jsonb, 0, 'Le titre fonctionne sur les deux plans.', 3),
    ('96c46ae8-5b32-590c-99de-0aeac4029bb1'::uuid, 'a57a24b0-3127-5477-8eae-d8347282c86c'::uuid, 'Quel drame frappe le petit Boris ?', 'mcq', '["Il est poussé au suicide par un pacte d’enfants","Il est enlevé","Il meurt de maladie","Il fugue"]'::jsonb, 0, 'La scène clôt le roman de façon brutale.', 4),
    ('ab44a1e6-8df9-5331-a0bd-e40118e2e20f'::uuid, 'a57a24b0-3127-5477-8eae-d8347282c86c'::uuid, 'Comment Gide qualifiait-il ce livre ?', 'mcq', '["Son seul « roman »","Une sotie","Un récit","Un essai"]'::jsonb, 0, 'Il réservait « récit » et « sotie » à ses autres livres.', 5),
    ('148dea74-5f2f-52d1-a439-45c75b3ddda8'::uuid, 'a57a24b0-3127-5477-8eae-d8347282c86c'::uuid, 'Le narrateur du roman reste neutre et invisible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il intervient, doute et commente ses propres personnages.', 6),
    ('90ccceb4-4a81-5a76-942e-23482c7526df'::uuid, '48eb2a1a-0816-5086-9ad1-2b0952551de4'::uuid, 'Que se passe-t-il à la publication de 1857 ?', 'mcq', '["Le recueil est condamné et six pièces sont retranchées","Il obtient un prix","Il est ignoré","Il est interdit en totalité"]'::jsonb, 0, 'La condamnation ne sera annulée qu’en 1949.', 1),
    ('09ba2aad-2f8c-5867-be42-d5760840d36c'::uuid, '48eb2a1a-0816-5086-9ad1-2b0952551de4'::uuid, 'Qu’est-ce que le spleen ?', 'mcq', '["Une angoisse sans objet, un ennui métaphysique","La nostalgie du pays natal","La colère politique","Le mal de mer"]'::jsonb, 0, '« Quand le ciel bas et lourd pèse comme un couvercle. »', 2),
    ('7b21a225-6d14-52e5-a7b4-560c1ae01e91'::uuid, '48eb2a1a-0816-5086-9ad1-2b0952551de4'::uuid, 'Quelle section a été ajoutée en 1861 ?', 'mcq', '["Tableaux parisiens","La Mort","Révolte","Le Vin"]'::jsonb, 0, 'Elle fait entrer la ville moderne dans le recueil.', 3),
    ('a291411f-8ae7-50ba-b130-0c29d84a6f77'::uuid, '48eb2a1a-0816-5086-9ad1-2b0952551de4'::uuid, 'Quelle formule résume l’alchimie poétique ?', 'mcq', '["« Tu m’as donné ta boue et j’en ai fait de l’or »","« Je est un autre »","« La poésie doit être faite par tous »","« Le vers libre est la liberté »"]'::jsonb, 0, 'La beauté naît du travail de la forme.', 4),
    ('da5373a5-a3fa-50a8-ba18-a220d3dbc282'::uuid, '48eb2a1a-0816-5086-9ad1-2b0952551de4'::uuid, 'Que dit le poème « Correspondances » ?', 'mcq', '["Parfums, couleurs et sons se répondent dans une forêt de symboles","La ville détruit la nature","Le poète est un albatros","La mort est un voyage"]'::jsonb, 0, 'C’est le fondement de la poétique symboliste.', 5),
    ('155ae145-6ebb-597c-89b8-5fbb775c728d'::uuid, '48eb2a1a-0816-5086-9ad1-2b0952551de4'::uuid, 'Baudelaire abandonne les formes fixes traditionnelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il garde sonnets et alexandrins : c’est la matière, non la forme, qui scandalise.', 6),
    ('12987c0c-fa9e-56c9-b7a2-03aa89e33fca'::uuid, '4b7f05f8-f0ed-5b05-98e6-310fef6c7e51'::uuid, 'Quel est le rôle de Scapin ?', 'mcq', '["Il mène toute l’intrigue pour aider les jeunes gens","Il trahit ses maîtres","Il est le père d’Octave","Il ne fait qu’observer"]'::jsonb, 0, 'Le valet est ici l’artiste de l’intrigue.', 1),
    ('c2a3430b-1c58-5838-b0ed-ba5e3e73efd7'::uuid, '4b7f05f8-f0ed-5b05-98e6-310fef6c7e51'::uuid, 'Quelle ruse Scapin emploie-t-il contre Géronte ?', 'mcq', '["Il lui fait croire que son fils est retenu sur une galère turque","Il falsifie un testament","Il l’accuse d’un crime","Il lui vole sa bourse"]'::jsonb, 0, '« Que diable allait-il faire dans cette galère ? »', 2),
    ('ca42cd03-fa49-5bc2-87cc-c342a6c8a1f6'::uuid, '4b7f05f8-f0ed-5b05-98e6-310fef6c7e51'::uuid, 'Quelle est la scène la plus célèbre de la pièce ?', 'mcq', '["Géronte enfermé dans un sac et battu","Le mariage d’Octave","La reconnaissance finale","Le duel de Léandre"]'::jsonb, 0, 'Un pur comique de gestes, hérité de la farce.', 3),
    ('ecc16cfd-9c11-55df-9770-d575921fa73c'::uuid, '4b7f05f8-f0ed-5b05-98e6-310fef6c7e51'::uuid, 'Comment se dénoue l’intrigue ?', 'mcq', '["Les jeunes filles se révèlent être les filles perdues des deux pères","Les pères cèdent par lassitude","Scapin achète les mariages","Les jeunes gens s’enfuient"]'::jsonb, 0, 'Reconnaissance : ressort classique de la comédie.', 4),
    ('80cb4644-8f6e-5228-9e80-0549b1048f28'::uuid, '4b7f05f8-f0ed-5b05-98e6-310fef6c7e51'::uuid, 'De quelle tradition théâtrale Scapin est-il issu ?', 'mcq', '["La commedia dell’arte, où il s’appelle Scapino","La tragédie grecque","Le théâtre espagnol","Le drame liturgique"]'::jsonb, 0, 'Boileau reprochera à Molière ce retour à la farce.', 5),
    ('d208c0fa-ab6a-5e0c-a73b-29bfd5b99826'::uuid, '4b7f05f8-f0ed-5b05-98e6-310fef6c7e51'::uuid, 'Scapin est puni à la fin de la pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il obtient son pardon en feignant d’être mourant.', 6),
    ('08cfe25e-de2e-59a2-b802-c3ea79cb4396'::uuid, '3b9c0813-8016-519a-8cfb-9060c38a59a3'::uuid, 'Sur quel fait la pièce est-elle fondée ?', 'mcq', '["L’attentat contre le grand-duc Serge, à Moscou en 1905","La révolution de 1917","La Commune de Paris","Un attentat imaginaire"]'::jsonb, 0, 'Camus s’est appuyé sur des sources historiques.', 1),
    ('22adb224-316e-5e6d-8f41-2b2fa62221ff'::uuid, '3b9c0813-8016-519a-8cfb-9060c38a59a3'::uuid, 'Pourquoi Kaliayev renonce-t-il au premier passage ?', 'mcq', '["Des enfants sont dans la calèche","La bombe est défectueuse","La police l’a repéré","Dora l’en empêche"]'::jsonb, 0, 'Le refus de tuer des innocents est le cœur de la pièce.', 2),
    ('80d8b588-f646-565d-bc13-1632614feb32'::uuid, '3b9c0813-8016-519a-8cfb-9060c38a59a3'::uuid, 'Que reproche Stepan à Kaliayev ?', 'mcq', '["D’avoir fait passer la morale avant l’efficacité révolutionnaire","D’avoir trahi le groupe","D’aimer Dora","D’avoir peur de mourir"]'::jsonb, 0, 'Deux conceptions de la révolution s’affrontent.', 3),
    ('4ab552d4-dd44-52b8-ab03-223dc85b9c9a'::uuid, '3b9c0813-8016-519a-8cfb-9060c38a59a3'::uuid, 'Que refuse Kaliayev en prison ?', 'mcq', '["La grâce et le marchandage proposés","De reconnaître son geste","De voir la grande-duchesse","De parler à ses camarades"]'::jsonb, 0, 'Il accepte d’être pendu : le prix du meurtre est sa propre vie.', 4),
    ('2ff00e22-ac3c-53a3-9c91-34040d97b39e'::uuid, '3b9c0813-8016-519a-8cfb-9060c38a59a3'::uuid, 'À quel cycle de l’œuvre de Camus la pièce appartient-elle ?', 'mcq', '["Le cycle de la révolte","Le cycle de l’absurde","Le cycle de l’amour","Aucun"]'::jsonb, 0, 'Avec L’Homme révolté, publié deux ans plus tard.', 5),
    ('fc134424-1b15-5970-8381-2493f5810663'::uuid, '3b9c0813-8016-519a-8cfb-9060c38a59a3'::uuid, 'Camus soutient que la fin justifie les moyens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il défend l’inverse : le révolté doit refuser de tuer des innocents et payer de sa vie.', 6),
    ('4c6107c3-522b-500f-91d9-06711fcdd838'::uuid, '2f0f3050-ae30-51c8-a505-20ce9162f80d'::uuid, 'Quelle est la forme du roman ?', 'mcq', '["Un roman épistolaire de 175 lettres","Un roman-mémoires","Un journal intime","Un dialogue"]'::jsonb, 0, 'Chaque lettre a son style et sa stratégie.', 1),
    ('8cf84fbd-4917-589a-afff-7d694e6acce8'::uuid, '2f0f3050-ae30-51c8-a505-20ce9162f80d'::uuid, 'Que veut la marquise de Merteuil au début ?', 'mcq', '["Se venger de Gercourt en faisant corrompre sa future épouse","Épouser Valmont","Ruiner Madame de Volanges","Quitter Paris"]'::jsonb, 0, 'Cécile de Volanges, sortie du couvent, en est la victime.', 2),
    ('bb6a1c7c-9968-5cc1-b27b-2881d362d62a'::uuid, '2f0f3050-ae30-51c8-a505-20ce9162f80d'::uuid, 'Quel est le pari de Valmont ?', 'mcq', '["Séduire la présidente de Tourvel, femme pieuse et mariée","Épouser Cécile","Ruiner Danceny","Provoquer Gercourt en duel"]'::jsonb, 0, 'L’enjeu est une nuit avec Merteuil.', 3),
    ('740a0b13-aba8-51a8-b2df-740d0eaaac9a'::uuid, '2f0f3050-ae30-51c8-a505-20ce9162f80d'::uuid, 'Qu’arrive-t-il à Valmont après sa conquête ?', 'mcq', '["Il tombe amoureux, rompt cruellement sur ordre de Merteuil et meurt en duel","Il épouse Tourvel","Il quitte la France","Il se retire au couvent"]'::jsonb, 0, 'Danceny le tue et reçoit les lettres de Merteuil.', 4),
    ('77d5a5a7-b253-522e-bdec-399d304eda57'::uuid, '2f0f3050-ae30-51c8-a505-20ce9162f80d'::uuid, 'Quelle lettre est célèbre pour son propos sur l’éducation des femmes ?', 'mcq', '["La lettre 81 de la marquise de Merteuil","La première lettre de Cécile","La dernière lettre de Tourvel","La lettre de rupture de Valmont"]'::jsonb, 0, 'Elle y raconte comment elle s’est formée pour survivre.', 5),
    ('d3398fd0-eb9d-5070-85e3-e848fd0cc7a0'::uuid, '2f0f3050-ae30-51c8-a505-20ce9162f80d'::uuid, 'La marquise de Merteuil échappe à toute sanction.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Démasquée, sifflée, ruinée et défigurée par la petite vérole, elle s’enfuit.', 6),
    ('47d91aba-8dc9-5303-88c8-a6847296c36e'::uuid, '265c5cec-1c3f-5921-9d1d-57b7b54fd9cd'::uuid, 'Que doit faire Hugo au début de l’histoire ?', 'mcq', '["Assassiner Hoederer, dirigeant accusé de trahison","Écrire un manifeste","Négocier avec le régent","Fuir à l’étranger"]'::jsonb, 0, 'Il devient son secrétaire et se met à l’admirer.', 1),
    ('ed773cb2-c771-5eb5-8618-f75b09b61a68'::uuid, '265c5cec-1c3f-5921-9d1d-57b7b54fd9cd'::uuid, 'Que signifie le titre de la pièce ?', 'mcq', '["L’action politique oblige à se salir les mains","Le crime laisse des traces","Le travail manuel est méprisé","La justice est corrompue"]'::jsonb, 0, '« Moi, j’ai les mains sales. Jusqu’aux coudes. »', 2),
    ('0993dd02-a5d5-596d-8919-5f7b03d58b55'::uuid, '265c5cec-1c3f-5921-9d1d-57b7b54fd9cd'::uuid, 'Pourquoi Hugo tire-t-il finalement ?', 'mcq', '["Par jalousie, en surprenant Jessica dans les bras d’Hoederer","Par conviction politique","Sur ordre direct du parti","Par accident"]'::jsonb, 0, 'L’ambiguïté du motif est le cœur de la pièce.', 3),
    ('854645ec-00d8-5788-91e5-4ccebba36413'::uuid, '265c5cec-1c3f-5921-9d1d-57b7b54fd9cd'::uuid, 'Que devient la ligne politique d’Hoederer ?', 'mcq', '["Elle est adoptée par le parti, qui le réhabilite","Elle est condamnée définitivement","Elle est oubliée","Elle provoque une scission"]'::jsonb, 0, 'Le meurtre devient rétrospectivement absurde.', 4),
    ('5ba44abd-6c8d-52e5-bb72-3115a01bbc75'::uuid, '265c5cec-1c3f-5921-9d1d-57b7b54fd9cd'::uuid, 'Comment Hugo se déclare-t-il à la fin ?', 'mcq', '["« Non récupérable »","« Innocent »","« Prêt à servir »","« Vaincu »"]'::jsonb, 0, 'Il refuse de renier son acte pour survivre.', 5),
    ('191f2d54-ee4d-5c96-a5e4-d209b4a6a5f7'::uuid, '265c5cec-1c3f-5921-9d1d-57b7b54fd9cd'::uuid, 'Sartre a favorisé les représentations de la pièce après 1948.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’a longtemps interdite, parce qu’elle servait l’anticommunisme.', 6),
    ('b074916e-e9c6-5ff6-b21b-adac0e6c587a'::uuid, '157d9cdb-ad22-558d-8018-5af1f8919332'::uuid, 'Pourquoi Jean Valjean a-t-il été envoyé au bagne ?', 'mcq', '["Pour un pain volé, puis des tentatives d’évasion","Pour meurtre","Pour vol de chandeliers","Pour désertion"]'::jsonb, 0, 'Dix-neuf ans au total.', 1),
    ('e2d4c44a-0431-5ac7-a043-b0a121667e8a'::uuid, '157d9cdb-ad22-558d-8018-5af1f8919332'::uuid, 'Quel geste transforme Jean Valjean ?', 'mcq', '["L’évêque Myriel lui offre les chandeliers qu’il vient de voler","Sa rencontre avec Cosette","La mort de Fantine","Son évasion du bagne"]'::jsonb, 0, 'C’est le point de départ de sa rédemption.', 2),
    ('f289c57a-6908-58e9-adc5-38d342ebb378'::uuid, '157d9cdb-ad22-558d-8018-5af1f8919332'::uuid, 'Qui poursuit Valjean sans relâche ?', 'mcq', '["L’inspecteur Javert","Thénardier","Marius","Le préfet Gisquet"]'::jsonb, 0, 'Épargné par Valjean, il se jette dans la Seine.', 3),
    ('e84e3eda-d1c4-5118-93c5-4bc3d521714a'::uuid, '157d9cdb-ad22-558d-8018-5af1f8919332'::uuid, 'Quel épisode historique le roman met-il en scène ?', 'mcq', '["L’insurrection républicaine de juin 1832","La Révolution de 1789","La Commune de 1871","Les Trois Glorieuses de 1830"]'::jsonb, 0, 'La barricade de la rue de la Chanvrerie en est le cœur.', 4),
    ('a05dee6e-6797-51a8-a96d-360660ee89e6'::uuid, '157d9cdb-ad22-558d-8018-5af1f8919332'::uuid, 'Comment Valjean sauve-t-il Marius ?', 'mcq', '["En le portant à travers les égouts de Paris","En le cachant au couvent","En négociant avec Javert","En le confiant à Gavroche"]'::jsonb, 0, 'La traversée des égouts est l’un des morceaux les plus célèbres.', 5),
    ('505ec609-43d3-5412-8227-9b74e8ac7112'::uuid, '157d9cdb-ad22-558d-8018-5af1f8919332'::uuid, 'Le roman a été écrit en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Hugo l’achève en exil, à Guernesey ; il paraît en 1862.', 6),
    ('85bf4bcf-5860-5063-92b1-0ecdad1e62af'::uuid, '1b0b8859-59c7-5f37-a16a-3b3a7c57aa1d'::uuid, 'Quelles sont les deux parties du livre ?', 'mcq', '["« Lire » et « Écrire »","« L’enfance » et « La guerre »","« Le père » et « Le grand-père »","« Avant » et « Après »"]'::jsonb, 0, 'Elles couvrent les dix premières années de Sartre.', 1),
    ('87940dbd-dfca-5445-ab0e-d247cae3438e'::uuid, '1b0b8859-59c7-5f37-a16a-3b3a7c57aa1d'::uuid, 'Chez qui Sartre grandit-il ?', 'mcq', '["Chez son grand-père Charles Schweitzer","Chez son père","Chez une tante en province","En pension"]'::jsonb, 0, 'Un appartement plein de livres, et un enfant unique adulé.', 2),
    ('bd638a1b-d255-5e7d-9619-576d14fe35f8'::uuid, '1b0b8859-59c7-5f37-a16a-3b3a7c57aa1d'::uuid, 'Quel regard Sartre porte-t-il sur son enfance ?', 'mcq', '["Un regard critique : il démonte la comédie qu’il jouait","Un regard nostalgique","Un regard indifférent","Un regard purement documentaire"]'::jsonb, 0, 'Il parle de sa « névrose littéraire ».', 3),
    ('f2a676ad-2c21-560f-b061-b943f0da0b16'::uuid, '1b0b8859-59c7-5f37-a16a-3b3a7c57aa1d'::uuid, 'Quelle conclusion tire-t-il sur la littérature ?', 'mcq', '["Elle ne sauve personne — mais il continue d’écrire","Elle est le seul salut","Elle doit être abandonnée","Elle remplace la politique"]'::jsonb, 0, '« Que faire d’autre ? »', 4),
    ('aacf2c8c-5746-5b95-90bb-c5c4d2438fab'::uuid, '1b0b8859-59c7-5f37-a16a-3b3a7c57aa1d'::uuid, 'Quel événement marque l’année de publication ?', 'mcq', '["Sartre refuse le prix Nobel","Il reçoit le Goncourt","Il fonde Les Temps modernes","Il quitte la France"]'::jsonb, 0, 'C’était en 1964.', 5),
    ('f3b0fa8d-7f8c-5e05-a4bb-22dbbb305cc7'::uuid, '1b0b8859-59c7-5f37-a16a-3b3a7c57aa1d'::uuid, 'Le livre couvre toute la vie de Sartre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’arrête à ses dix ans environ.', 6),
    ('1f4dd358-69d1-5eae-b3d1-44548287c6e6'::uuid, '863387ed-ddb2-5257-bc5d-71bf2fdaf8f7'::uuid, 'Que symbolisent les mouches d’Argos ?', 'mcq', '["Le remords collectif entretenu par le pouvoir","La peste","La guerre","La misère du peuple"]'::jsonb, 0, 'Égisthe et Jupiter s’en servent pour tenir la ville.', 1),
    ('2b56940a-7bf6-5152-881f-45af05ee3de9'::uuid, '863387ed-ddb2-5257-bc5d-71bf2fdaf8f7'::uuid, 'En quoi Oreste diffère-t-il d’Électre après le meurtre ?', 'mcq', '["Il assume entièrement son acte, elle s’effondre dans le remords","Il fuit, elle reste","Il pardonne, elle se venge encore","Il se tue, elle règne"]'::jsonb, 0, 'Assumer ses actes est la seule dignité selon Sartre.', 2),
    ('7b0e5840-4319-562c-967c-e88477ceef9d'::uuid, '863387ed-ddb2-5257-bc5d-71bf2fdaf8f7'::uuid, 'Quel rôle joue Jupiter dans la pièce ?', 'mcq', '["Il soutient l’ordre du remords et propose le pardon","Il aide Oreste","Il est absent","Il punit Égisthe"]'::jsonb, 0, 'Oreste lui oppose sa liberté : « je suis ma liberté ».', 3),
    ('118894ab-83d0-5256-ab4d-9927c0debebd'::uuid, '863387ed-ddb2-5257-bc5d-71bf2fdaf8f7'::uuid, 'En quelle année la pièce a-t-elle été créée ?', 'mcq', '["1943, sous l’Occupation","1938","1946","1951"]'::jsonb, 0, 'Le message était lisible pour qui savait lire.', 4),
    ('0082e42d-1364-5658-bb8c-59a165495039'::uuid, '863387ed-ddb2-5257-bc5d-71bf2fdaf8f7'::uuid, 'Comment Oreste quitte-t-il la ville ?', 'mcq', '["En entraînant les mouches derrière lui","En fuyant de nuit","Escorté par l’armée","Il ne la quitte pas"]'::jsonb, 0, 'Comme le joueur de flûte de Hamelin.', 5),
    ('22c569a7-a1f5-53c8-931d-c9da3fa69093'::uuid, '863387ed-ddb2-5257-bc5d-71bf2fdaf8f7'::uuid, 'La pièce défend l’idée d’une nature humaine fixe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle affirme l’inverse : l’homme est sa liberté et se définit par ses actes.', 6),
    ('00a864e2-48db-5b35-ac32-c0087fc89235'::uuid, '4ec4b287-4e25-5f8d-a4a2-79686ebb859a'::uuid, 'À qui le livre s’adresse-t-il ?', 'mcq', '["À Nathanaël, disciple imaginaire","À sa femme Madeleine","Au lecteur anonyme","À Paul Valéry"]'::jsonb, 0, 'L’apostrophe donne au livre sa forme d’enseignement.', 1),
    ('1fc4f898-8f28-54e8-98f8-79cd1c6f4086'::uuid, '4ec4b287-4e25-5f8d-a4a2-79686ebb859a'::uuid, 'Quel enseignement Gide y délivre-t-il ?', 'mcq', '["La ferveur, le désir et la disponibilité au monde sensible","La discipline et l’étude","La foi protestante","Le renoncement au monde"]'::jsonb, 0, 'Fruits, soif, vent et villes d’Afrique du Nord en sont la matière.', 2),
    ('0dae40c2-1abd-5b9f-b6ce-afeec43ac58b'::uuid, '4ec4b287-4e25-5f8d-a4a2-79686ebb859a'::uuid, 'Quelle formule célèbre exprime le refus des attaches ?', 'mcq', '["« Familles, je vous hais ! »","« Il faut cultiver notre jardin »","« Je hais les voyages »","« Tout est vanité »"]'::jsonb, 0, 'Le livre rejette possessions, habitudes et doctrines.', 3),
    ('0537140b-6866-5f51-962f-fbf2f1bad993'::uuid, '4ec4b287-4e25-5f8d-a4a2-79686ebb859a'::uuid, 'Qu’ordonne la dernière page au lecteur ?', 'mcq', '["Jeter le livre","Le relire","Le transmettre","L’apprendre par cœur"]'::jsonb, 0, '« Que mon livre t’enseigne à t’intéresser plus à toi qu’à lui-même. »', 4),
    ('1073e42b-efa8-5f52-9556-eb7c92d5eb2f'::uuid, '4ec4b287-4e25-5f8d-a4a2-79686ebb859a'::uuid, 'Comment le livre a-t-il été reçu à sa parution ?', 'mcq', '["Il est passé presque inaperçu, avant de devenir culte","Il a été un succès immédiat","Il a été censuré","Il a été salué par l’Académie"]'::jsonb, 0, 'Une cinquantaine d’exemplaires vendus en dix ans.', 5),
    ('7f28c1a7-36c9-5d0b-95de-74ec15f15c5d'::uuid, '4ec4b287-4e25-5f8d-a4a2-79686ebb859a'::uuid, 'Le livre appartient à un genre littéraire bien défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est inclassable : proses, fragments, rondes, journal de voyage.', 6),
    ('481149c5-ffcd-5d43-afa8-e315b97a7081'::uuid, '68e28a02-e0cc-5a13-8582-8019812ac015'::uuid, 'Quelle particularité présente cette pièce dans l’œuvre de Racine ?', 'mcq', '["C’est sa seule comédie","C’est sa première tragédie","Elle est en prose","Elle est inachevée"]'::jsonb, 0, 'Elle s’inspire des Guêpes d’Aristophane.', 1),
    ('e23392a3-5f71-5b0f-a7df-b77be0e247db'::uuid, '68e28a02-e0cc-5a13-8582-8019812ac015'::uuid, 'De quelle manie le juge Dandin souffre-t-il ?', 'mcq', '["Il ne peut s’empêcher de juger","Il refuse de juger","Il est avare","Il est jaloux"]'::jsonb, 0, 'Son fils doit l’enfermer pour l’en empêcher.', 2),
    ('afe11625-cd17-5176-8fff-9a3ce5b0dd95'::uuid, '68e28a02-e0cc-5a13-8582-8019812ac015'::uuid, 'Quel procès burlesque est organisé pour le calmer ?', 'mcq', '["Celui d’un chien accusé d’avoir mangé un chapon","Celui d’un domestique voleur","Celui de la comtesse de Pimbesche","Celui de son propre fils"]'::jsonb, 0, 'On produit même les chiots du prévenu.', 3),
    ('cb4d6ce2-c27a-5ddb-aae3-21dbdf0dc857'::uuid, '68e28a02-e0cc-5a13-8582-8019812ac015'::uuid, 'Qui plaide dans ce faux procès ?', 'mcq', '["Petit Jean et L’Intimé","Chicanneau et Dandin","Léandre et Isabelle","La comtesse seule"]'::jsonb, 0, 'La parodie de l’éloquence judiciaire est le sommet comique.', 4),
    ('574fdcd6-da95-5ec1-9181-4cdfc334b3c0'::uuid, '68e28a02-e0cc-5a13-8582-8019812ac015'::uuid, 'Que vise la satire de la pièce ?', 'mcq', '["La justice et la manie procédurière","La médecine","La noblesse de cour","L’Église"]'::jsonb, 0, 'Racine s’y amuse de l’univers judiciaire de son temps.', 5),
    ('8793ef24-b91f-5a5b-a215-1777ee5250ca'::uuid, '68e28a02-e0cc-5a13-8582-8019812ac015'::uuid, 'Racine a écrit plusieurs comédies après celle-ci.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est resté un unicum : une récréation de virtuose.', 6),
    ('c21d5a11-239a-5338-bbf0-b8c5228949ff'::uuid, '12512af7-8037-5abb-9781-23dc55a2aa94'::uuid, 'Quels poètes figurent dans la première édition ?', 'mcq', '["Corbière, Rimbaud et Mallarmé","Baudelaire, Hugo et Vigny","Laforgue, Cros et Nouveau","Musset, Nerval et Gautier"]'::jsonb, 0, 'Trois inconnus ou méprisés de leur temps.', 1),
    ('75655399-97d3-598a-8ebc-632d490ea14b'::uuid, '12512af7-8037-5abb-9781-23dc55a2aa94'::uuid, 'Qui se cache derrière « Pauvre Lelian » ?', 'mcq', '["Paul Verlaine lui-même, par anagramme","Rimbaud","Mallarmé","Villiers de L’Isle-Adam"]'::jsonb, 0, 'Il s’ajoute à sa propre liste dans la seconde édition.', 2),
    ('097a8fd6-b78d-56f1-ab9e-0031c432c965'::uuid, '12512af7-8037-5abb-9781-23dc55a2aa94'::uuid, 'Quel effet le livre a-t-il eu ?', 'mcq', '["Il a fait connaître des œuvres qui seraient restées invisibles","Il a fait scandale sans conséquence","Il a été interdit","Il a nui à la réputation des poètes cités"]'::jsonb, 0, 'Sans lui, Corbière n’aurait pas survécu.', 3),
    ('e02e0c13-e57b-51e2-96e7-661fbfc952f4'::uuid, '12512af7-8037-5abb-9781-23dc55a2aa94'::uuid, 'D’où vient le mot « maudit » appliqué aux poètes ?', 'mcq', '["De Baudelaire, dans Les Fleurs du mal","De Hugo","De Verlaine seul","De Rimbaud"]'::jsonb, 0, 'Le poème « Bénédiction » en donne l’idée.', 4),
    ('d181f1cf-8119-59ff-bc9b-1f43b0470f5b'::uuid, '12512af7-8037-5abb-9781-23dc55a2aa94'::uuid, 'Quelle est la forme des textes ?', 'mcq', '["Des essais-portraits citant longuement les poèmes","Des poèmes","Des lettres ouvertes","Des préfaces d’éditions"]'::jsonb, 0, 'La citation abondante fait tout le travail de découverte.', 5),
    ('26c31432-1565-5bb2-8d7e-b3925220dba1'::uuid, '12512af7-8037-5abb-9781-23dc55a2aa94'::uuid, 'Une seule femme figure parmi les poètes présentés.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Marceline Desbordes-Valmore, ajoutée dans la seconde édition.', 6),
    ('446a02ce-f047-5157-b18d-30441932ff12'::uuid, 'ec6b5309-1d69-5ee8-90cc-951baa631252'::uuid, 'Pourquoi Magdelon et Cathos éconduisent-elles leurs prétendants ?', 'mcq', '["Ils manquent d’élégance et de galanterie selon les codes des romans","Ils sont pauvres","Elles en aiment d’autres","Gorgibus s’y oppose"]'::jsonb, 0, 'Elles ont la tête pleine de romans précieux.', 1),
    ('303685ce-42b9-50b7-96cb-2ab5477135a0'::uuid, 'ec6b5309-1d69-5ee8-90cc-951baa631252'::uuid, 'Quelle vengeance les prétendants organisent-ils ?', 'mcq', '["Ils envoient leurs valets déguisés en marquis et vicomte","Ils enlèvent les jeunes filles","Ils dénoncent Gorgibus","Ils quittent Paris"]'::jsonb, 0, 'Mascarille et Jodelet séduisent aussitôt les précieuses.', 2),
    ('3ff8d504-5943-5c62-b89b-66af89f0ffd5'::uuid, 'ec6b5309-1d69-5ee8-90cc-951baa631252'::uuid, 'Quelle périphrase désigne les fauteuils dans la pièce ?', 'mcq', '["« Les commodités de la conversation »","« Les conseillers des grâces »","« Les trônes du repos »","« Les amis du corps »"]'::jsonb, 0, 'Le miroir, lui, est « le conseiller des grâces ».', 3),
    ('b40c3d18-0d34-577d-82ad-94d26b21ffa7'::uuid, 'ec6b5309-1d69-5ee8-90cc-951baa631252'::uuid, 'Que vise exactement la satire ?', 'mcq', '["La caricature provinciale de la préciosité, le snobisme du langage","Les femmes savantes en général","La noblesse de cour","Les romans de chevalerie"]'::jsonb, 0, 'La préciosité réelle était un mouvement animé par des femmes cultivées.', 4),
    ('354bc1ad-4090-5a83-b813-9192c337d80c'::uuid, 'ec6b5309-1d69-5ee8-90cc-951baa631252'::uuid, 'Quel rôle cette pièce a-t-elle joué dans la carrière de Molière ?', 'mcq', '["Elle l’a lancé à Paris en 1659","Elle l’a fait interdire","Elle a mis fin à sa troupe","Elle est restée inédite"]'::jsonb, 0, 'Le succès fut immédiat et considérable.', 5),
    ('52622dad-0c10-50b7-998a-2fdb30fee43f'::uuid, 'ec6b5309-1d69-5ee8-90cc-951baa631252'::uuid, 'La pièce est écrite en cinq actes et en vers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une farce en un acte et en prose.', 6),
    ('2138d017-7bba-58a7-8c82-6f2214da77eb'::uuid, 'c9c3a95c-a703-5fb7-a79a-c54e4b4f1527'::uuid, 'Qui Pascal défend-il dans ces lettres ?', 'mcq', '["Antoine Arnauld et les jansénistes de Port-Royal","Les jésuites","La Sorbonne","Le roi"]'::jsonb, 0, 'Elles paraissent sous le pseudonyme de Louis de Montalte.', 1),
    ('850d95e4-f194-5cdf-aa24-a4b93fd558ad'::uuid, 'c9c3a95c-a703-5fb7-a79a-c54e4b4f1527'::uuid, 'Qu’attaque Pascal chez les jésuites ?', 'mcq', '["La casuistique, qui permet de tout justifier","Leur enseignement du latin","Leur richesse foncière","Leur position politique seule"]'::jsonb, 0, 'Le duel, l’usure et la « restriction mentale » y passent.', 2),
    ('ff025c61-1117-52bd-821e-305f2eb359be'::uuid, 'c9c3a95c-a703-5fb7-a79a-c54e4b4f1527'::uuid, 'Quel procédé emploient les premières lettres ?', 'mcq', '["La feinte naïveté d’un provincial qui demande des explications","La démonstration théologique","Le récit autobiographique","La satire en vers"]'::jsonb, 0, 'On découvre que les mots employés ne signifient rien de précis.', 3),
    ('9b44c53e-5b35-578d-b34b-c0c3fedbc26e'::uuid, 'c9c3a95c-a703-5fb7-a79a-c54e4b4f1527'::uuid, 'Combien de lettres composent l’ensemble ?', 'mcq', '["Dix-huit","Sept","Trente","Douze"]'::jsonb, 0, 'Publiées entre 1656 et 1657.', 4),
    ('972d0b53-7d3f-5082-93f9-ea2836ace6ce'::uuid, 'c9c3a95c-a703-5fb7-a79a-c54e4b4f1527'::uuid, 'Quel jugement Voltaire portait-il sur ce livre ?', 'mcq', '["Le premier livre de prose française vraiment moderne","Un ouvrage illisible","Un texte purement théologique","Un pamphlet sans style"]'::jsonb, 0, 'La limpidité et l’ironie y ont fait école.', 5),
    ('83544465-86d0-5cd0-a1b4-44a368c83d61'::uuid, 'c9c3a95c-a703-5fb7-a79a-c54e4b4f1527'::uuid, 'Les Provinciales ont été publiées avec l’accord des autorités.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Clandestines, elles ont été condamnées et brûlées.', 6),
    ('7ec9bcf6-f0b9-510d-9cd7-753c64a4762c'::uuid, 'e290c338-1159-5c5b-8ce0-759c8bbe955d'::uuid, 'Pourquoi les Joad quittent-ils l’Oklahoma ?', 'mcq', '["Le Dust Bowl, les dettes et les tracteurs des banques les chassent","Une inondation","Une épidémie","Une guerre"]'::jsonb, 0, 'Des prospectus leur promettent du travail en Californie.', 1),
    ('c5b22f9e-8920-53fe-98ba-65f690ffbce7'::uuid, 'e290c338-1159-5c5b-8ce0-759c8bbe955d'::uuid, 'Par quelle route partent-ils ?', 'mcq', '["La route 66","La route de l’Oregon","La route côtière","La piste Santa Fe"]'::jsonb, 0, 'Elle est devenue mythique grâce à ce roman.', 2),
    ('48b73b24-9658-5c48-b430-c82baed332a2'::uuid, 'e290c338-1159-5c5b-8ce0-759c8bbe955d'::uuid, 'Que trouvent-ils en Californie ?', 'mcq', '["Des camps sordides et des salaires écrasés","Le travail promis","Des terres à acheter","Un accueil syndical organisé"]'::jsonb, 0, 'Les récoltes sont même détruites pour maintenir les prix.', 3),
    ('27e9f1c5-6c4c-5b78-9640-296f6f160a02'::uuid, 'e290c338-1159-5c5b-8ce0-759c8bbe955d'::uuid, 'Qui est Casy ?', 'mcq', '["Un ancien pasteur devenu syndicaliste, tué pendant une grève","Le père de famille","Un propriétaire californien","Le mari de Rose de Saron"]'::jsonb, 0, 'Tom Joad le venge et doit fuir.', 4),
    ('eb24d5d5-4f6a-59c8-99e5-7c3e8dc3f24a'::uuid, 'e290c338-1159-5c5b-8ce0-759c8bbe955d'::uuid, 'Sur quelle scène le roman se termine-t-il ?', 'mcq', '["Rose de Saron donne le sein à un homme mourant de faim","Le retour en Oklahoma","Une grève victorieuse","La mort de Tom"]'::jsonb, 0, 'La fin, très commentée, a beaucoup choqué à l’époque.', 5),
    ('3eeef532-0a3a-561a-a787-6753f1796b44'::uuid, 'e290c338-1159-5c5b-8ce0-759c8bbe955d'::uuid, 'Le roman a été aussitôt salué partout aux États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a été brûlé et interdit dans certains comtés avant de devenir un classique.', 6),
    ('e47b4c74-7d7a-50bf-9782-339613c44e7b'::uuid, 'ca70f396-f4ec-5201-8532-aadfec85ddf3'::uuid, 'Quel poème ouvre le recueil ?', 'mcq', '["Fonction du poète","Tristesse d’Olympio","Oceano nox","Guitare"]'::jsonb, 0, 'Il assigne au poète une mission de guide et de voyant.', 1),
    ('6a7765d5-9821-54b3-b1e6-1bf0ab1bc835'::uuid, 'ca70f396-f4ec-5201-8532-aadfec85ddf3'::uuid, 'Que raconte « Tristesse d’Olympio » ?', 'mcq', '["Le retour dans un lieu aimé où la nature a tout oublié","Un naufrage","La mort d’un ami","Une bataille"]'::jsonb, 0, 'À comparer avec « Le Lac » de Lamartine et « Souvenir » de Musset.', 2),
    ('52a17640-9397-589a-ad7c-c9336fc5e002'::uuid, 'ca70f396-f4ec-5201-8532-aadfec85ddf3'::uuid, 'Quel poème évoque les marins disparus en mer ?', 'mcq', '["Oceano nox","Fonction du poète","Guitare","Tristesse d’Olympio"]'::jsonb, 0, 'Les familles y attendent des hommes qui ne reviendront pas.', 3),
    ('86166222-b4e6-5baf-a631-d8594c151bad'::uuid, 'ca70f396-f4ec-5201-8532-aadfec85ddf3'::uuid, 'Que désignent les « rayons » et les « ombres » ?', 'mcq', '["L’élan prophétique et le deuil, les deux versants du recueil","Le jour et la nuit d’une journée","La ville et la campagne","Le passé et l’avenir politiques"]'::jsonb, 0, 'Le titre annonce la double tonalité.', 4),
    ('6cb8af13-8bea-5b1e-bdab-6b9aef6690b2'::uuid, 'ca70f396-f4ec-5201-8532-aadfec85ddf3'::uuid, 'Combien de temps Hugo attend-il avant de republier des vers ?', 'mcq', '["Treize ans, jusqu’aux Châtiments en 1853","Deux ans","Vingt-cinq ans","Cinq ans"]'::jsonb, 0, 'Entre-temps : le théâtre, la politique, le deuil et l’exil.', 5),
    ('45185768-4632-5960-8b61-c91d6d6aa1ef'::uuid, 'ca70f396-f4ec-5201-8532-aadfec85ddf3'::uuid, 'Ce recueil marque le passage du poète intime au poète public.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est précisément ce que « Fonction du poète » annonce.', 6),
    ('dcbbf21a-ade7-5b0b-8691-f74cfdb3ec2d'::uuid, '5d4b5a76-9fde-54a7-af71-abc2bbffac92'::uuid, 'D’où vient d’Artagnan ?', 'mcq', '["De Gascogne","De Bretagne","De Provence","De Picardie"]'::jsonb, 0, 'Il monte à Paris pour entrer chez les mousquetaires du roi.', 1),
    ('c85f3794-5f87-5fff-a47d-785935037ce0'::uuid, '5d4b5a76-9fde-54a7-af71-abc2bbffac92'::uuid, 'Comment se lie-t-il aux trois mousquetaires ?', 'mcq', '["Après avoir failli se battre en duel avec les trois le même jour","Ils étaient amis d’enfance","Ils l’ont recruté","Il les sauve d’une embuscade"]'::jsonb, 0, 'L’arrivée des gardes du cardinal les rend alliés.', 2),
    ('1bf7b104-5988-5582-b4ec-014184057376'::uuid, '5d4b5a76-9fde-54a7-af71-abc2bbffac92'::uuid, 'Quelle mission les mène à Londres ?', 'mcq', '["Récupérer les ferrets de diamants de la reine","Assassiner Buckingham","Négocier un traité","Escorter le roi"]'::jsonb, 0, 'L’honneur d’Anne d’Autriche est en jeu.', 3),
    ('c68c9b2c-e6b7-5813-b79a-9e400960061a'::uuid, '5d4b5a76-9fde-54a7-af71-abc2bbffac92'::uuid, 'Qui est Milady de Winter ?', 'mcq', '["Une espionne du cardinal, ancienne épouse d’Athos","La sœur de Buckingham","La suivante de la reine","La mère de Constance"]'::jsonb, 0, 'Elle porte une fleur de lys marquée à l’épaule.', 4),
    ('c306bc0d-e6e3-53c2-8c2d-70e95892886c'::uuid, '5d4b5a76-9fde-54a7-af71-abc2bbffac92'::uuid, 'Quelle devise le roman a-t-il rendue célèbre ?', 'mcq', '["« Un pour tous, tous pour un »","« Tout pour l’honneur »","« Servir le roi »","« Rien sans peine »"]'::jsonb, 0, 'Elle est passée dans la langue courante.', 5),
    ('a02ba20b-959a-5c49-9551-3a484166dbb4'::uuid, '5d4b5a76-9fde-54a7-af71-abc2bbffac92'::uuid, 'Dumas a écrit ce roman seul.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Auguste Maquet a largement collaboré à sa documentation et à sa trame.', 6),
    ('d96925ed-2cd0-54f6-988a-5d3ec8e72708'::uuid, 'c25eeb59-8529-5381-8bbe-1a49e4ffe17f'::uuid, 'Combien de sonnets le recueil compte-t-il ?', 'mcq', '["Cent dix-huit","Cinquante","Deux cents","Douze"]'::jsonb, 0, 'Ciselés pendant trente ans.', 1),
    ('7fcea2fa-652d-5196-b15d-c56682847ac2'::uuid, 'c25eeb59-8529-5381-8bbe-1a49e4ffe17f'::uuid, 'À quel mouvement Heredia appartient-il ?', 'mcq', '["Le Parnasse","Le symbolisme","Le romantisme","Le surréalisme"]'::jsonb, 0, 'Impersonnalité, culte de la forme, érudition.', 2),
    ('86f06ae4-3470-596f-89b4-1249aa78118a'::uuid, 'c25eeb59-8529-5381-8bbe-1a49e4ffe17f'::uuid, 'Comment le recueil est-il organisé ?', 'mcq', '["Comme une traversée de l’histoire, de la Grèce aux Tropiques","Par ordre alphabétique","Par ordre de composition","En quatre saisons"]'::jsonb, 0, 'Chaque section correspond à une époque ou à un espace.', 3),
    ('d04b91f6-eb08-5773-aec6-2b3c685590fa'::uuid, 'c25eeb59-8529-5381-8bbe-1a49e4ffe17f'::uuid, 'Quel poème évoque les conquistadors ?', 'mcq', '["Les Conquérants","Antoine et Cléopâtre","Le Récif de corail","Soir de bataille"]'::jsonb, 0, '« Comme un vol de gerfauts hors du charnier natal… »', 4),
    ('f7d89844-9b17-5951-ac27-cc1094a9aa18'::uuid, 'c25eeb59-8529-5381-8bbe-1a49e4ffe17f'::uuid, 'Sur quoi repose l’effet d’un sonnet de Heredia ?', 'mcq', '["Un dernier vers frappant, souvent une vision colorée","Une morale explicite","Un récit complet","Un dialogue"]'::jsonb, 0, 'Le sonnet se referme comme un objet fini.', 5),
    ('e94d4bfd-6cd6-5c24-a7a2-4cf1bc31c4ac'::uuid, 'c25eeb59-8529-5381-8bbe-1a49e4ffe17f'::uuid, 'Heredia a publié de nombreux recueils.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les Trophées est son unique recueil, publié en 1893.', 6),
    ('dcd87eb7-cae7-5763-a92c-ea851d29383c'::uuid, 'f1f3070d-6381-5e3e-a1e9-2ecdafb42cb1'::uuid, 'Quelle image donne son titre au recueil ?', 'mcq', '["Un rossignol ligoté par les vrilles, qui chante pour ne plus dormir","Une vigne gelée","Un vendangeur au travail","Un jardin abandonné"]'::jsonb, 0, 'C’est un art poétique en miniature.', 1),
    ('8ccceb79-2abf-58fa-84dd-efba390293de'::uuid, 'f1f3070d-6381-5e3e-a1e9-2ecdafb42cb1'::uuid, 'De quoi le recueil est-il composé ?', 'mcq', '["De textes brefs : chroniques, souvenirs, dialogues, poèmes en prose","D’un roman continu","De poèmes en vers","D’une pièce de théâtre"]'::jsonb, 0, 'Ils avaient d’abord paru dans la presse.', 2),
    ('171e5059-6d59-5b45-b74b-05b5c645f175'::uuid, 'f1f3070d-6381-5e3e-a1e9-2ecdafb42cb1'::uuid, 'Qui sont Toby-Chien et Kiki-la-Doucette ?', 'mcq', '["Les animaux de Colette, qui dialoguent dans plusieurs textes","Deux amis d’enfance","Des personnages de music-hall","Ses frères"]'::jsonb, 0, 'L’animal a chez elle un statut de personnage.', 3),
    ('71b6b684-5aa2-51c2-b200-9d1312bc6674'::uuid, 'f1f3070d-6381-5e3e-a1e9-2ecdafb42cb1'::uuid, 'Sous quel nom Colette publiait-elle auparavant ?', 'mcq', '["Willy, le nom de son mari","Sido","Gabrielle Colette","Un pseudonyme masculin inventé"]'::jsonb, 0, 'Les Claudine avaient paru sous ce nom.', 4),
    ('dea50b43-24e4-57b7-aeec-6223cb081b12'::uuid, 'f1f3070d-6381-5e3e-a1e9-2ecdafb42cb1'::uuid, 'À quelle œuvre ce recueil est-il associé au programme du bac ?', 'mcq', '["Sido","La Maison de Claudine","Le Blé en herbe","La Naissance du jour"]'::jsonb, 0, 'Sous le parcours « la célébration du monde ».', 5),
    ('76139e65-21f5-5aae-a593-881b1aa1dedc'::uuid, 'f1f3070d-6381-5e3e-a1e9-2ecdafb42cb1'::uuid, 'Le recueil raconte une histoire suivie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un ensemble de textes courts sans intrigue commune.', 6),
    ('edd18edd-c574-5d03-8160-ade83ccfddaf'::uuid, 'cd599949-0023-5f89-a8f3-fa4194dd7a9b'::uuid, 'À qui le poème liminaire est-il adressé ?', 'mcq', '["À Elsa Triolet, sa femme","À sa mère","À la France","À un compagnon de résistance"]'::jsonb, 0, 'Elle donne son nom au recueil.', 1),
    ('56ed099f-bdd5-54bc-916e-83d6d3669e4b'::uuid, 'cd599949-0023-5f89-a8f3-fa4194dd7a9b'::uuid, 'Que permet la « contrebande » poétique d’Aragon ?', 'mcq', '["Faire passer un message de résistance sous l’amour et le Moyen Âge","Publier à l’étranger","Utiliser un pseudonyme","Imprimer sur papier clandestin"]'::jsonb, 0, 'La censure allemande n’y voyait que des poèmes d’amour.', 2),
    ('fe20077d-f16c-55ad-9fa1-c66539def1b3'::uuid, 'cd599949-0023-5f89-a8f3-fa4194dd7a9b'::uuid, 'Quel poème évoque la défaite de mai 1940 ?', 'mcq', '["Les Lilas et les Roses","Zone libre","Richard Cœur-de-Lion","Plus belle que les larmes"]'::jsonb, 0, 'Les fleurs du printemps y accompagnent l’exode.', 3),
    ('ea856f7e-c6c0-5408-8bd7-cd5ecec51a24'::uuid, 'cd599949-0023-5f89-a8f3-fa4194dd7a9b'::uuid, 'Que défend Aragon dans sa préface ?', 'mcq', '["Le retour à la rime et au vers régulier","Le vers libre","Le poème en prose","L’écriture automatique"]'::jsonb, 0, 'Une poésie qui se retient par cœur se transmet clandestinement.', 4),
    ('1ac9e565-5585-5a3a-81df-99acf28c716d'::uuid, 'cd599949-0023-5f89-a8f3-fa4194dd7a9b'::uuid, 'Quelle invention formelle lui doit-on ?', 'mcq', '["La rime enjambée","Le calligramme","Le verset","Le sonnet renversé"]'::jsonb, 0, 'La fin d’un vers y rime avec le début du suivant.', 5),
    ('ace5ecf3-6e8d-5fff-9fa3-14e9bd2bb1ae'::uuid, 'cd599949-0023-5f89-a8f3-fa4194dd7a9b'::uuid, 'Aragon vient du surréalisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il en fut l’un des fondateurs avant de rompre avec Breton.', 6),
    ('28a2ca46-d79b-5cfa-933c-82ebb57d0e8f'::uuid, '917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Qu’avait proposé d’Alembert dans l’Encyclopédie ?', 'mcq', '["Ouvrir un théâtre à Genève","Interdire les fêtes publiques","Réformer l’Église genevoise","Créer une académie"]'::jsonb, 0, 'Rousseau, citoyen de Genève, répond par une lettre publique.', 1),
    ('dfe4ceaa-e824-59e2-a04a-bd1965139e1d'::uuid, '917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Quel est le principal reproche de Rousseau au théâtre ?', 'mcq', '["Il amollit les mœurs et remplace l’action par les larmes","Il coûte trop cher","Il est réservé aux nobles","Il ne respecte pas la religion"]'::jsonb, 0, 'Les larmes fictives tiennent lieu de vertu réelle.', 2),
    ('8ce9dc53-aa32-5888-8e21-d6b1e41fff32'::uuid, '917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Quelle pièce Rousseau attaque-t-il longuement ?', 'mcq', '["Le Misanthrope de Molière","Phèdre de Racine","Le Cid de Corneille","Tartuffe"]'::jsonb, 0, 'Il reproche à Molière de faire rire de l’homme vertueux.', 3),
    ('ec466b3b-c7c0-5bd5-b79e-7387d12e9b15'::uuid, '917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Que propose Rousseau à la place du théâtre ?', 'mcq', '["Des fêtes publiques en plein air où le peuple est acteur","Des lectures privées","Des concerts religieux","Rien du tout"]'::jsonb, 0, '« Plantez au milieu d’une place un piquet couronné de fleurs… »', 4),
    ('ae13f7e2-a7a0-5446-95e5-d55df9b9044c'::uuid, '917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Quelle conséquence ce texte a-t-il eue ?', 'mcq', '["La rupture définitive avec Diderot et les Encyclopédistes","Son expulsion de Genève","Son entrée à l’Académie","L’interdiction du théâtre en France"]'::jsonb, 0, 'La brouille était latente ; elle devient publique.', 5),
    ('57ca2fde-17c0-5544-85a0-a1ad831d3675'::uuid, '917a22d6-781f-5e44-85d6-4c566236de61'::uuid, 'Rousseau reproche au spectacle d’isoler ceux qui s’y rassemblent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '« On croit s’assembler au spectacle, et c’est là que chacun s’isole. »', 6),
    ('9160ba01-545e-5961-8f8f-2867eafa143e'::uuid, 'e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Sur quel support Zilia écrit-elle d’abord ?', 'mcq', '["Des quipus, cordelettes nouées incas","Du parchemin","Des tablettes de cire","Des feuilles de palmier"]'::jsonb, 0, 'Elle passe ensuite au français, qu’elle apprend.', 1),
    ('4cf6f9bd-ea96-59f2-aae4-0812dca5b076'::uuid, 'e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Quel procédé argumentatif le roman emploie-t-il ?', 'mcq', '["Le regard éloigné : une étrangère décrit nos usages","La démonstration philosophique","La fable animalière","Le dialogue socratique"]'::jsonb, 0, 'Ce que l’habitude rend invisible devient absurde.', 2),
    ('fa1191e6-04c8-539a-b3bd-ba76ad66b67f'::uuid, 'e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Quelle critique sociale domine le roman ?', 'mcq', '["L’éducation des femmes, réduite aux ornements","La fiscalité","La politique coloniale espagnole seule","L’organisation judiciaire"]'::jsonb, 0, 'C’est la dénonciation la plus célèbre de l’œuvre.', 3),
    ('0df26eba-df35-5087-9f39-2d4c09cc847d'::uuid, 'e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Zilia refuse Aza et Déterville et choisit l’étude et l’amitié","Elle épouse Déterville","Elle retrouve Aza et l’épouse","Elle meurt de chagrin"]'::jsonb, 0, 'Un dénouement inouï pour le roman de l’époque.', 4),
    ('fc8f748c-52e3-59df-abe3-72444ed89ba5'::uuid, 'e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Quel fut le sort du livre après le XVIIIe siècle ?', 'mcq', '["Oublié, puis redécouvert par la critique féministe","Toujours au programme","Interdit","Traduit dans toutes les langues sans interruption"]'::jsonb, 0, 'Il avait pourtant connu plus de quarante éditions.', 5),
    ('77cc4a4b-30cd-57e8-aff6-c7f1df4b1298'::uuid, 'e9a08b00-b769-52ac-a104-5d4a53cd47e1'::uuid, 'Zilia comprend le français dès son arrivée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’apprend peu à peu : le roman est aussi un récit d’apprentissage.', 6),
    ('428ba704-5be1-5b0b-83b9-7f3323a9229d'::uuid, 'f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'Quel est le dispositif fictif du recueil ?', 'mcq', '["Un narrateur écrit depuis un vieux moulin de Provence","Un voyageur écrit d’Italie","Un curé raconte ses paroissiens","Un meunier tient son journal"]'::jsonb, 0, 'Daudet vivait en réalité à Paris et ne possédait pas ce moulin.', 1),
    ('495a3beb-28e8-56e7-b0a7-3eff4c7d825c'::uuid, 'f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'Que raconte « La Chèvre de M. Seguin » ?', 'mcq', '["Une chèvre préfère une nuit de liberté et la mort au piquet","Une chèvre perdue retrouvée","Un troupeau décimé","Un berger et son loup apprivoisé"]'::jsonb, 0, 'La lettre conseille à un poète de ne pas quitter son emploi.', 2),
    ('f0ca8cbf-a9d0-58c2-a9d5-19e5a4bd240d'::uuid, 'f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'Quel est le secret de maître Cornille ?', 'mcq', '["Il feint de moudre alors que la minoterie à vapeur a tout emporté","Il cache un trésor","Il vend de la farine frelatée","Il a vendu son moulin"]'::jsonb, 0, 'Le conte dit la fin d’un monde artisanal.', 3),
    ('9e071e6a-32b2-576d-a12e-116fedfef42b'::uuid, 'f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'Quelle tonalité domine sous l’humour ?', 'mcq', '["La mélancolie d’une Provence qui disparaît","La colère politique","L’exaltation religieuse","L’angoisse fantastique"]'::jsonb, 0, 'Moulins ruinés, traditions perdues, villages vidés.', 4),
    ('b08e9d4e-8efa-57a2-a813-4864d1a5b6b0'::uuid, 'f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'En quelle année le recueil paraît-il ?', 'mcq', '["1869","1885","1850","1900"]'::jsonb, 0, 'Les textes avaient d’abord paru dans la presse.', 5),
    ('a323bf7a-7bc5-51b7-bfa6-f03d5d48b2f5'::uuid, 'f384bb84-8faf-5cad-9ac0-765cf684de34'::uuid, 'Ce sont des contes uniquement destinés aux enfants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Souvent lus comme tels, ils sont bien plus amers qu’il n’y paraît.', 6),
    ('41ba8c80-f1e2-5c77-ba68-d5babf1712b9'::uuid, 'f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Combien de lettres composent le roman ?', 'mcq', '["161","50","99","300"]'::jsonb, 0, 'Écrites par une quinzaine de correspondants.', 1),
    ('2b05f25b-2bbc-5388-8329-60d65e806fa5'::uuid, 'f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Comment Rica décrit-il le roi de France ?', 'mcq', '["Comme un grand magicien","Comme un tyran","Comme un sage","Comme un guerrier"]'::jsonb, 0, 'Il fait croire que le papier est de l’argent.', 2),
    ('17e08afb-9df6-5216-aee7-149157227302'::uuid, 'f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Que raconte l’apologue des Troglodytes ?', 'mcq', '["Un peuple égoïste s’autodétruit, une communauté vertueuse prospère puis demande un roi","La fondation de la Perse","Un naufrage","Une guerre de religion"]'::jsonb, 0, 'Il annonce De l’esprit des lois.', 3),
    ('85668ccb-4221-5017-9639-cb76da7eea1c'::uuid, 'f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Que révèle la dernière lettre de Roxane ?', 'mcq', '["Elle a trahi Usbek, s’est empoisonnée et ne l’a jamais aimé","Elle s’est enfuie","Elle a pris le pouvoir au sérail","Elle demande pardon"]'::jsonb, 0, 'Le penseur de la liberté était un despote chez lui.', 4),
    ('076edb52-f4b4-5456-9021-804a2315e56c'::uuid, 'f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Que représente le sérail ?', 'mcq', '["Un modèle réduit du despotisme, qui s’écroule faute de lois","Un décor exotique","Un souvenir d’enfance","Une utopie"]'::jsonb, 0, 'Surveillance, peur et punitions y remplacent le droit.', 5),
    ('db7991eb-a1c4-526e-b57b-ec07b96f4d64'::uuid, 'f3ca6d88-a7d9-5f78-a5f5-37fd5d86d9b6'::uuid, 'Le roman a été publié sous le nom de Montesquieu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Publication anonyme à Amsterdam, pour échapper à la censure.', 6),
    ('e755c0f8-d83e-5a08-b1f6-7f15d31215d4'::uuid, '2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'À qui la plupart des lettres sont-elles adressées ?', 'mcq', '["À sa fille, Madame de Grignan","Au roi","À son mari","À La Fontaine"]'::jsonb, 0, 'Son départ pour la Provence en 1671 déclenche l’écriture.', 1),
    ('80ab84bd-7cc2-59ed-9e43-89453ba3bca5'::uuid, '2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'Quelle mort célèbre Madame de Sévigné raconte-t-elle ?', 'mcq', '["Celle de Vatel, qui se transperce de son épée","Celle de Molière","Celle du roi","Celle de Fouquet"]'::jsonb, 0, 'La marée n’était pas arrivée pour le repas royal.', 2),
    ('7922cc6e-34ad-54e4-9922-cdc81ff269b7'::uuid, '2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'Quand ces lettres ont-elles été publiées ?', 'mcq', '["Après sa mort, à partir de 1725","De son vivant","Au XIXe siècle seulement","Jamais intégralement"]'::jsonb, 0, 'Elle n’écrivait pas pour être publiée.', 3),
    ('809e7567-519c-50b4-b604-b2f7603bcb9e'::uuid, '2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'Qu’est-ce qui caractérise son style ?', 'mcq', '["La vivacité et l’oralité : « je vous écris comme je vous parle »","La solennité","L’obscurité savante","La brièveté systématique"]'::jsonb, 0, 'Elle écrit sans se relire, au fil de l’instant.', 4),
    ('f27bdda2-6a60-5dd2-bfa8-34c345c3725e'::uuid, '2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'Quels sujets aborde-t-elle ?', 'mcq', '["La cour, les nouvelles, mais aussi la santé, le temps et la campagne","La politique étrangère seule","La théologie","Le commerce"]'::jsonb, 0, 'C’est le XVIIe siècle vu par ses détails.', 5),
    ('0b9da57f-1e5f-5c0d-b301-30cfafe09c74'::uuid, '2eb5353b-ffde-5d30-a40c-51e4fd33e3e2'::uuid, 'Ses lettres ont fait de la correspondance un genre littéraire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles ont été admirées et imitées, notamment par Proust.', 6),
    ('245c49b2-eb64-5959-a05e-aacf10b6efb0'::uuid, 'cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Pourquoi Lorenzo se fait-il le compagnon de débauche du duc ?', 'mcq', '["Pour l’approcher et le tuer","Par goût du plaisir","Pour obtenir une charge","Par peur des représailles"]'::jsonb, 0, 'Le rôle finit par le transformer réellement.', 1),
    ('f14ead20-2fd7-5e9d-9e59-a385cfd6a787'::uuid, 'cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Quelle phrase résume sa transformation ?', 'mcq', '["« Le vice a été pour moi un vêtement, maintenant il est collé à ma peau »","« Je suis ma liberté »","« Tout est perdu »","« Le monde est un théâtre »"]'::jsonb, 0, 'Le masque est devenu le visage.', 2),
    ('609e3496-c1ae-547f-b413-bfb581c9a862'::uuid, 'cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Que se passe-t-il après le meurtre du duc ?', 'mcq', '["Rien ne change : un nouveau duc est installé aussitôt","La République est proclamée","Le peuple se soulève","Florence est libérée"]'::jsonb, 0, 'Les républicains ne bougent pas.', 3),
    ('a117f2ce-5495-599a-a5f7-d306d1d4a510'::uuid, 'cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Pourquoi la pièce fut-elle longtemps injouable ?', 'mcq', '["Trente-neuf scènes, quarante personnages, changements de lieu constants","Elle était censurée","Elle était inachevée","Elle était écrite en italien"]'::jsonb, 0, 'Elle est créée seulement en 1896, avec Sarah Bernhardt.', 4),
    ('7f35e430-a627-5086-8f01-aa83243ca0ef'::uuid, 'cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Quelle désillusion politique la pièce transpose-t-elle ?', 'mcq', '["Celle des républicains après 1830","Celle de 1789","Celle de 1848","Celle de l’Empire"]'::jsonb, 0, 'Musset écrit quatre ans après les Trois Glorieuses.', 5),
    ('bb0487d6-286f-5e7f-aff8-6c0590250630'::uuid, 'cd51584d-8ad9-5e82-a8e4-682190b36035'::uuid, 'Lorenzo devient un héros célébré après son geste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est assassiné à Venise pour la prime mise sur sa tête.', 6),
    ('f4b504ed-ffa2-5c98-8091-b862da2d6bf3'::uuid, '11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'Pourquoi Lucien est-il chassé de Polytechnique ?', 'mcq', '["Pour ses opinions républicaines","Pour un duel","Pour des dettes","Pour insuffisance de résultats"]'::jsonb, 0, 'Son père lui achète ensuite un poste d’officier à Nancy.', 1),
    ('644fd34e-0c54-5547-9e32-4f5b1887afef'::uuid, '11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'Qui est Madame de Chasteller ?', 'mcq', '["Une jeune veuve légitimiste dont Lucien tombe amoureux","La femme de son colonel","Sa cousine","Une actrice parisienne"]'::jsonb, 0, 'Une machination le fait renoncer à elle.', 2),
    ('1106b361-a4d3-5f89-a048-84ff5ed5324a'::uuid, '11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'Que découvre Lucien au ministère de l’Intérieur ?', 'mcq', '["La corruption électorale de la monarchie de Juillet","Un complot étranger","La faillite de l’État","Un trafic d’armes"]'::jsonb, 0, 'Achat de voix, préfets aux ordres, candidatures officielles.', 3),
    ('6f17019e-dd2c-5d8c-9491-d808b3f26289'::uuid, '11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'Quel est l’état du roman ?', 'mcq', '["Inachevé, publié seulement en 1894","Achevé et publié en 1835","Publié en feuilleton","Perdu puis reconstitué"]'::jsonb, 0, 'Une troisième partie, à Rome, n’a jamais été écrite.', 4),
    ('60e1d6e6-40d9-533a-99fe-cf6cf4f34aec'::uuid, '11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'Quel personnage secondaire est particulièrement réussi ?', 'mcq', '["Monsieur Leuwen père, banquier cynique et généreux","Le colonel Filloteau","Le docteur Du Poirier","Madame Grandet"]'::jsonb, 0, 'Il est l’un des plus séduisants personnages de Stendhal.', 5),
    ('a8ef2923-bf3f-5505-b3ac-8c46612e4d03'::uuid, '11c1f94c-8dfa-5236-96a9-8a0b6dfa4515'::uuid, 'C’est le roman le plus politique de Stendhal.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il documente de l’intérieur le régime de Louis-Philippe.', 6),
    ('42f5ad26-d9dd-5d62-b100-58019d75e237'::uuid, '4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Qu’est-ce qui nourrit les rêves d’Emma ?', 'mcq', '["Les romans sentimentaux lus au couvent","Les voyages","Le théâtre parisien","Les récits de sa mère"]'::jsonb, 0, 'L’écart entre ces rêves et la vie provinciale la détruit.', 1),
    ('8806f1aa-6e9c-5551-b42c-101063adfd2c'::uuid, '4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Qui sont ses deux amants ?', 'mcq', '["Léon et Rodolphe","Homais et Lheureux","Charles et Léon","Rodolphe et Binet"]'::jsonb, 0, 'Rodolphe l’abandonne par une lettre lâche.', 2),
    ('49e90b85-bbe9-53d9-8e67-f8247cdeb3bf'::uuid, '4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Qui pousse Emma à s’endetter ?', 'mcq', '["Le marchand Lheureux","Le notaire Guillaumin","Homais","Rodolphe"]'::jsonb, 0, 'La saisie imminente précipite le dénouement.', 3),
    ('e7e60cd7-8eae-5771-928a-1945547722fc'::uuid, '4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Comment Emma meurt-elle ?', 'mcq', '["Elle avale de l’arsenic","Elle se noie","Elle meurt en couches","Elle est tuée en duel"]'::jsonb, 0, 'L’agonie est décrite avec une précision clinique.', 4),
    ('7d282ac4-3d63-5bee-807e-077e1ec85b44'::uuid, '4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Que désigne le « bovarysme » ?', 'mcq', '["L’insatisfaction née de l’écart entre le rêve et la vie","Le goût de la province","La passion de la lecture","L’adultère bourgeois"]'::jsonb, 0, 'Le mot est passé dans la langue courante.', 5),
    ('acec451f-3af3-565b-88e2-a1aa4e5108ef'::uuid, '4dfced30-1a1a-5518-b5b2-71d1fa2e0daf'::uuid, 'Le roman a été condamné lors de son procès.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Flaubert a été acquitté en 1857 ; Baudelaire, la même année, fut condamné.', 6),
    ('675384aa-a5fe-5af4-a938-34e66287239a'::uuid, '5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'Qui est Théodore de Sérannes ?', 'mcq', '["Madeleine de Maupin, déguisée en homme","Un ami de d’Albert","Le frère de Rosette","Un acteur de théâtre"]'::jsonb, 0, 'Elle veut observer les hommes tels qu’ils sont entre eux.', 1),
    ('457bbb01-d38f-564a-bae6-d9d07b891d2c'::uuid, '5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'Quelle doctrine la préface proclame-t-elle ?', 'mcq', '["L’art pour l’art","Le réalisme","L’art social","Le naturalisme"]'::jsonb, 0, '« Il n’y a de vraiment beau que ce qui ne peut servir à rien. »', 2),
    ('d54865f5-d9c7-5fb1-9f5b-2c8835eece18'::uuid, '5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'Quelle pièce est jouée dans le roman ?', 'mcq', '["Comme il vous plaira, de Shakespeare","Le Cid","Le Misanthrope","Roméo et Juliette"]'::jsonb, 0, 'Les rôles travestis y révèlent les désirs de chacun.', 3),
    ('14a01ee1-ba21-5d28-bb9a-b376195830cf'::uuid, '5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'De quelle figure historique le personnage s’inspire-t-il ?', 'mcq', '["Julie d’Aubigny, cantatrice et duelliste","Ninon de Lenclos","Jeanne d’Arc","George Sand"]'::jsonb, 0, 'Elle avait défrayé la chronique au XVIIe siècle.', 4),
    ('580ef00f-b408-5384-a505-a5430e499b82'::uuid, '5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'Pourquoi le roman fit-il scandale ?', 'mcq', '["Par son sujet : travestissement et ambiguïté du désir","Par ses attaques politiques","Par son athéisme","Par sa violence"]'::jsonb, 0, 'Il fut longtemps mis à l’index.', 5),
    ('0e70cbf0-4b7b-5a26-a55d-34f79fbd9edd'::uuid, '5aa51e44-0e6e-5111-88f4-e3d2f11cbd02'::uuid, 'La préface est aujourd’hui plus célèbre que le roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est le manifeste de l’art pour l’art, cité dans tous les manuels.', 6),
    ('bb8f7d31-361f-5892-9191-a5e921178589'::uuid, '5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'Qui sont les Valeureux ?', 'mcq', '["Des cousins juifs de Céphalonie, menés par Mangeclous","Des résistants français","Des diplomates genevois","Des marchands vénitiens"]'::jsonb, 0, 'Ils entreprennent le voyage pour rejoindre Solal.', 1),
    ('7fbbbac1-4ba8-51c5-8ed9-08f3ed44717a'::uuid, '5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'Quel personnage donne son titre au roman ?', 'mcq', '["Mangeclous, avocat et menteur de génie","Saltiel","Solal","Mattathias"]'::jsonb, 0, 'Faux médecin, faux prophète, inventeur permanent.', 2),
    ('e7a9def7-a8fd-52d5-8f44-45986f5f1cf1'::uuid, '5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'À quel cycle le livre appartient-il ?', 'mcq', '["Celui de Solal et des Valeureux, qui mène à Belle du Seigneur","Les Rougon-Macquart","La Comédie humaine","Aucun"]'::jsonb, 0, 'Solal (1930), Mangeclous (1938), Belle du Seigneur (1968), Les Valeureux (1969).', 3),
    ('3619dd98-39f6-5b1d-9114-6fb40265d105'::uuid, '5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'Quel registre domine le livre ?', 'mcq', '["La truculence verbale et le comique","Le tragique","Le fantastique","Le didactique"]'::jsonb, 0, 'Discours interminables, listes et exagérations.', 4),
    ('6547c015-8836-5134-b885-13548fa0f709'::uuid, '5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'Que célèbre le livre sous le rire ?', 'mcq', '["Un monde juif méditerranéen menacé","La Genève internationale","La bourgeoisie française","L’aventure maritime"]'::jsonb, 0, 'Il paraît en 1938 : le contexte donne au rire son amertume.', 5),
    ('7f6cd11d-66de-5aa9-9606-860728e13024'::uuid, '5417eac7-8e45-586a-bdc4-a694b863aacc'::uuid, 'Solal est le personnage principal de ce roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les Valeureux, et Mangeclous au premier chef, qui occupent le devant.', 6),
    ('090fc857-8ee9-5b9a-9f01-332c635413fd'::uuid, '3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Comment Breton définit-il le surréalisme ?', 'mcq', '["Un automatisme psychique pur, hors du contrôle de la raison","Un art de la beauté formelle","Un réalisme approfondi","Une poésie engagée"]'::jsonb, 0, 'La définition est restée célèbre mot pour mot.', 1),
    ('1402ada6-deac-59b1-bc67-019328ac9e2c'::uuid, '3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Quelle pratique le manifeste met-il en avant ?', 'mcq', '["L’écriture automatique","Le sonnet","La description minutieuse","La versification régulière"]'::jsonb, 0, 'Expérimentée dans Les Champs magnétiques, avec Soupault.', 2),
    ('b2bb8bce-a4ef-5674-85ac-f4bdd736de7d'::uuid, '3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Sur quelle théorie de l’image Breton s’appuie-t-il ?', 'mcq', '["Celle de Reverdy : rapprocher deux réalités éloignées","Celle de Boileau","Celle de Baudelaire seul","Celle d’Aristote"]'::jsonb, 0, 'Plus l’écart est grand et juste, plus l’image est forte.', 3),
    ('2a4bdd34-24be-5a43-9f5d-d261e21851c4'::uuid, '3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Quel savant inspire le mouvement ?', 'mcq', '["Freud","Darwin","Pasteur","Einstein"]'::jsonb, 0, 'Le rêve et l’inconscient deviennent matière poétique.', 4),
    ('ada5c63c-7721-50d7-b4be-f5baf91d37cc'::uuid, '3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Quel genre le manifeste tourne-t-il en dérision ?', 'mcq', '["Le roman réaliste et ses descriptions","Le théâtre","La poésie lyrique","L’essai"]'::jsonb, 0, 'Breton se moque des portraits et des décors de roman.', 5),
    ('84c5c012-53df-5486-9223-c6b63113a464'::uuid, '3c968e24-748e-5e6b-b320-4c09a1e2e3ce'::uuid, 'Il n’y a eu qu’un seul manifeste du surréalisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un second paraît en 1930, avec son lot d’exclusions.', 6),
    ('2961291d-4800-5628-83de-da36c87c7de7'::uuid, 'b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Que découvre Manon dans les collines ?', 'mcq', '["La source qui alimente tout le village","Un trésor","Un document notarié","La tombe de son père"]'::jsonb, 0, 'Elle comprend alors ce que les Soubeyran avaient fait.', 1),
    ('7ef3bec0-e361-553d-bc9e-1eecf8dea828'::uuid, 'b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Comment se venge-t-elle ?', 'mcq', '["Elle obstrue la source du village","Elle dénonce les Soubeyran","Elle incendie leur ferme","Elle porte plainte"]'::jsonb, 0, 'Les fontaines se tarissent et la panique s’installe.', 2),
    ('17a5e50c-d38b-523a-80af-a701eb0a3d3e'::uuid, 'b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Que devient Ugolin ?', 'mcq', '["Amoureux de Manon et repoussé, il se pend","Il quitte le village","Il épouse Manon","Il est arrêté"]'::jsonb, 0, 'Sa passion précipite la catastrophe.', 3),
    ('019003c3-9184-504e-a4d7-75fdb8429375'::uuid, 'b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Que révèle la vieille Delphine au Papet ?', 'mcq', '["Jean de Florette était son propre fils","Manon est sa petite-fille par alliance","La source appartenait à la commune","Ugolin l’avait trahi"]'::jsonb, 0, 'Il a tué son enfant sans le savoir.', 4),
    ('1106d6de-1d1a-5c87-9a05-e014cec20d62'::uuid, 'b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Comment le village est-il puni ?', 'mcq', '["Collectivement, par la soif","Par un procès","Par un incendie","Il ne l’est pas"]'::jsonb, 0, 'Son silence l’avait rendu complice.', 5),
    ('fc5a53fb-10de-51d6-a472-8eb19173bafa'::uuid, 'b8a0c811-5683-50cd-912f-62f0cb0b4198'::uuid, 'Manon reste enfermée dans sa vengeance à la fin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle épouse l’instituteur : le cycle se referme sans la détruire.', 6),
    ('323aa3dc-15fe-505a-8c44-294067e7c137'::uuid, 'cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Qui raconte l’histoire ?', 'mcq', '["Des Grieux, dont le récit est rapporté par Renoncour","Manon","Un narrateur omniscient","Tiberge"]'::jsonb, 0, 'Nous ne voyons Manon que par les yeux de celui qui l’aime.', 1),
    ('ba455e87-ab78-5401-86e7-d79dd432ad3e'::uuid, 'cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Où les deux personnages se rencontrent-ils ?', 'mcq', '["À Amiens","À Paris","Au Havre","À Calais"]'::jsonb, 0, 'Elle allait au couvent, il était promis à l’ordre de Malte.', 2),
    ('5d97a62a-5c44-5510-996d-9586838c5980'::uuid, 'cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Quel événement marque la rechute de Des Grieux ?', 'mcq', '["Manon reparaît le jour de sa thèse en Sorbonne","Il perd sa fortune au jeu","Son père le déshérite","Tiberge le trahit"]'::jsonb, 0, 'Il croyait pourtant être guéri de sa passion.', 3),
    ('a6b61751-330e-5978-b798-57fcd59c95b5'::uuid, 'cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Où Manon meurt-elle ?', 'mcq', '["Dans le désert de Louisiane","À l’Hôpital de Paris","Sur le navire","À Saint-Lazare"]'::jsonb, 0, 'Des Grieux l’enterre de ses mains.', 4),
    ('97492c87-2787-5f3f-adc8-6d2084e88b00'::uuid, 'cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Quel personnage incarne la morale et l’amitié ?', 'mcq', '["Tiberge","Lescaut","M. de B…","Synnelet"]'::jsonb, 0, 'Toujours écouté, jamais suivi.', 5),
    ('aa63d2be-dd16-57d4-b336-3e538f475864'::uuid, 'cd8455ef-e97e-51ac-8549-afb46b246906'::uuid, 'Le roman donne accès aux pensées de Manon.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Son opacité est un choix de construction : elle reste insaisissable.', 6),
    ('5d897222-73a1-5f24-97b7-d93c6badfba4'::uuid, '80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'En quelle année le recueil paraît-il ?', 'mcq', '["1820","1830","1857","1800"]'::jsonb, 0, 'On y voit l’acte de naissance du romantisme français en poésie.', 1),
    ('d1099b58-3844-5e66-a36d-69675b243ad9'::uuid, '80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'Quel est le poème le plus célèbre du recueil ?', 'mcq', '["Le Lac","L’Automne","Le Vallon","Le Golfe de Baya"]'::jsonb, 0, '« Ô temps, suspends ton vol ! »', 2),
    ('3687c2e3-766e-5117-992f-c8b8428ffc54'::uuid, '80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'Qui est Elvire ?', 'mcq', '["Julie Charles, la femme aimée et morte","Une figure mythologique","La mère du poète","Sa fille"]'::jsonb, 0, 'Sa mort inspire les plus beaux poèmes du recueil.', 3),
    ('5a52423c-9d06-5324-b568-b127c4579dd5'::uuid, '80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'Quel rôle la nature joue-t-elle ?', 'mcq', '["Confidente et miroir de l’âme, elle dure quand l’homme passe","Un simple décor","Une force hostile","Un objet d’étude scientifique"]'::jsonb, 0, 'C’est l’un des traits distinctifs du romantisme.', 4),
    ('fb9cc0e1-2071-577c-ab05-282a41386ee4'::uuid, '80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'Quelle formule de « L’Isolement » est restée célèbre ?', 'mcq', '["« Un seul être vous manque, et tout est dépeuplé »","« Je est un autre »","« Le ciel est par-dessus le toit »","« Sois sage, ô ma Douleur »"]'::jsonb, 0, 'Elle a été mille fois citée depuis.', 5),
    ('8fee3fe8-c080-5bc7-996d-6379380fd313'::uuid, '80fc7737-516d-5f7d-9d95-8188125753d3'::uuid, 'Lamartine rompt avec la versification classique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il garde l’alexandrin et les strophes régulières : c’est le ton et le sujet qui changent.', 6),
    ('da922cd7-4c20-5bbd-9634-31046bbfa7ac'::uuid, '03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Quelle est la forme du livre ?', 'mcq', '["Une longue lettre d’Hadrien à Marc Aurèle","Un journal quotidien","Un dialogue","Un récit à la troisième personne"]'::jsonb, 0, 'Un mourant y reprend toute sa vie.', 1),
    ('8f6f91c2-1764-561d-9b9e-379e52f7a9bc'::uuid, '03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Qui est Antinoüs ?', 'mcq', '["Le jeune homme aimé d’Hadrien, noyé dans le Nil","Son général","Son médecin","Son successeur"]'::jsonb, 0, 'Hadrien le divinise et ne s’en console pas.', 2),
    ('3082dbdb-818e-512d-b1b7-96f6226b5a3b'::uuid, '03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Quelle politique impériale Hadrien mène-t-il ?', 'mcq', '["Il arrête l’expansion et consolide les frontières","Il conquiert la Perse","Il abandonne la Bretagne","Il transfère la capitale"]'::jsonb, 0, 'Le mur de Bretagne en est le symbole.', 3),
    ('82849ded-4535-5544-94b0-a4f451fce4b6'::uuid, '03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Combien de temps Yourcenar a-t-elle mis à écrire ce livre ?', 'mcq', '["Près de trente ans","Deux ans","Six mois","Dix ans"]'::jsonb, 0, 'Les Carnets de notes racontent cette longue élaboration.', 4),
    ('01eb36b1-a4af-5070-bb76-9d27b7c0d2cf'::uuid, '03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Quelle formule résume sa méthode ?', 'mcq', '["« Un pied dans l’érudition, l’autre dans la magie »","« Le roman est un miroir »","« Je peins le passage »","« Écrire, c’est se souvenir »"]'::jsonb, 0, 'Documentation historique et reconstruction intérieure.', 5),
    ('b71b65f1-be12-5e1e-852a-40eb087e9ada'::uuid, '03e5a9cc-a59e-5028-a4bf-20e40918c609'::uuid, 'Yourcenar fut la première femme élue à l’Académie française.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'En 1980, près de trente ans après ce livre.', 6)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 264 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 264 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
